const PAGES = {"/":{"canonical":"https://www.dcpp-digital.de/","markdown":"# DCPP Digital – Webdesign, App-Entwicklung, Content und Publishing\n\nDCPP Digital aus Bottrop entwickelt digitale Auftritte und Produkte für Selbstständige, kleine Unternehmen und Marken. Die Zusammenarbeit kann digital auch deutschlandweit erfolgen.\n\nKanonische Website: https://www.dcpp-digital.de/\nTextgrundlage: bestätigter Stand V6.7.12, 24.10.2026.\n\n[DCPP Digital – eckiges D-Arrow-Signet](https://www.dcpp-digital.de/#dcpp-start)\n\n[Start](https://www.dcpp-digital.de/#dcpp-start) [Leistungen](https://www.dcpp-digital.de/#dcpp-services) [Projekte](https://www.dcpp-digital.de/#dcpp-projects) [Ablauf](https://www.dcpp-digital.de/#dcpp-process) [Kontakt](https://www.dcpp-digital.de/#dcpp-contact)\n\nDCPP DIGITAL\n\nDevelop•Content•Create\n\n# Ideen werden digital.\n\nWebdesign, Apps & Publishing aus Bottrop\n\nDigitale Lösungen für Unternehmen, Selbstständige und eigene Marken – von der ersten Idee bis zur Veröffentlichung.\n\n[Projekte ansehen](https://www.dcpp-digital.de/#dcpp-projects) [Leistungen](https://www.dcpp-digital.de/#dcpp-services)\n\nDCPP Digital D-Pfeil-Signet\n\nDCPP Digital Develop • Content • Create Ideen werden digital.\n\nWebseiten\n\nApps\n\nContent & Brand\n\nDigital-Publishing\n\nLEISTUNGEN\n\n## Klarer Umfang. Klare Ergebnisse.\n\nDCPP Digital entwickelt Webseiten, Apps und Publishing-Projekte mit klar definiertem Ziel und Leistungsumfang. Vor der Umsetzung wird festgelegt, was entsteht, was dafür\nbenötigt wird und welche Leistungen ausdrücklich nicht Bestandteil des Projekts sind.\n\n### Webdesign\n\nIndividuelle Business-Webseiten mit klarer Nutzerführung, responsivem Aufbau und einer visuellen Sprache, die zur Marke und zum tatsächlichen Geschäftsziel passt.\n\nLeistung im Detail+\n\nFür wen?\n\nSelbstständige, lokale Unternehmen, Dienstleister und kleine Betriebe, die eine neue Website benötigen oder einen bestehenden Auftritt grundlegend verbessern\nmöchten.\n\nWas bekommen Sie?\n\nKonzept, Seitenstruktur, responsive Gestaltung, technische Umsetzung, klare Kontaktwege, Basis-SEO/GEO und eine veröffentlichungsfähige Website im vereinbarten\nUmfang.\n\nWie läuft es ab?\n\nZiel und Bestand klären → Struktur festlegen → Design entwickeln → technisch umsetzen → mobil und funktional prüfen → veröffentlichen.\n\nWas wird benötigt?\n\nUnternehmensdaten, Ziele, gewünschte Inhalte und Kontaktwege sowie vorhandene Texte, Bilder, Logos und Zugänge, soweit sie für das Projekt benötigt werden.\n\nNicht automatisch enthalten\n\nLaufende redaktionelle Betreuung, bezahlte Werbung, kostenpflichtige Drittanbieter, individuelle Rechtsberatung sowie Leistungen außerhalb des vereinbarten\nProjektumfangs.\n\n[Webprojekte ansehen →](https://www.dcpp-digital.de/#dcpp-websites)\n\n### App-Entwicklung\n\nDigitale Produkte von der Funktionsidee über UX und Interface bis zum Prototyp, Testbuild und zur technischen Umsetzung eines klar abgegrenzten Funktionsumfangs.\n\nLeistung im Detail+\n\nFür wen?\n\nSelbstständige, Marken und Projektstarter mit einer konkreten App-Idee oder einem klaren digitalen Anwendungsfall, der zunächst strukturiert und testbar\numgesetzt werden soll.\n\nWas bekommen Sie?\n\nFunktionskonzept, priorisierten MVP-Umfang, UX/UI, technische Umsetzung im vereinbarten Rahmen sowie – je nach Projekt – Prototyp, Testbuild und\nWeiterentwicklungsgrundlage.\n\nWie läuft es ab?\n\nAnwendungsfall definieren → Kernfunktionen priorisieren → UX/UI entwickeln → Testversion bauen → prüfen → gezielt weiterentwickeln.\n\nWas wird benötigt?\n\nIdee und Zielgruppe, gewünschter Nutzen, Muss-Funktionen, vorhandene Markeninhalte sowie regelmäßiges Feedback während der Test- und Entwicklungsphase.\n\nNicht automatisch enthalten\n\nStore-Gebühren, kostenpflichtige APIs oder Plattformdienste, laufende Serverkosten, garantierte Store-Freigaben, dauerhafter Betrieb sowie rechtliche oder\nregulatorische Prüfungen.\n\n[App-Projekte ansehen →](https://www.dcpp-digital.de/#dcpp-apps)\n\n### Content & Brand\n\nEntwicklung eigenständiger Content-Marken, visueller Systeme und kanalübergreifender Auftritte mit klarer Wiedererkennbarkeit – projektbezogen und passend zum jeweiligen\nFormat.\n\n[Content-Projekte ansehen →](https://www.dcpp-digital.de/#dcpp-content)\n\n### Publishing\n\nEntwicklung von Büchern, Workbooks und digitalen Produkten – von Konzept, Inhalt und Gestaltung bis zur technisch publikationsfähigen Datei und Produktdarstellung.\n\nLeistung im Detail+\n\nFür wen?\n\nAutorinnen und Autoren, Selbstständige, Creator und kleine Marken, die ein Buch, Workbook, PDF-Produkt oder anderes Publishing-Projekt professionell umsetzen\nmöchten.\n\nWas bekommen Sie?\n\nKonzept und Inhaltsstruktur, Gestaltung und Layout, Cover- bzw. Produktdarstellung, technische Aufbereitung für das Zielmedium und publikationsfähige Dateien\nim vereinbarten Umfang.\n\nWie läuft es ab?\n\nThema und Zielgruppe klären → Inhalt strukturieren → Design entwickeln → Format- und Plattformvorgaben umsetzen → prüfen → Veröffentlichung vorbereiten.\n\nWas wird benötigt?\n\nThema, Zielgruppe, vorhandene Inhalte und ausschließlich Materialien, an denen die notwendigen Nutzungsrechte bestehen, sowie die gewünschte\nVeröffentlichungsplattform.\n\nNicht automatisch enthalten\n\nDruck- und Plattformkosten, Vertriebsgarantien, umfangreiches Lektorat oder Korrektorat außerhalb des vereinbarten Umfangs sowie individuelle Steuer- oder\nRechtsberatung.\n\n[Publishing-Projekte ansehen →](https://www.dcpp-digital.de/#dcpp-publishing)\n\nDer konkrete Leistungsumfang wird vor Projektstart abgestimmt. Zusätzliche Funktionen, Fremdkosten oder externe Dienste werden nicht stillschweigend vorausgesetzt, sondern vor der\nUmsetzung transparent eingeordnet.\n\nPROJEKTE\n\n## Digital entwickelt. Visuell eigenständig.\n\nNicht nur zeigen, was entstanden ist – sondern welches Problem gelöst, wie umgesetzt und welcher Stand erreicht wurde.\n\nBUSINESS-WEBSEITE\n\n[Die Blumen Boutique](https://www.dcpp-digital.de/?projekt=blumen-boutique)\n\nLIVEWEBSITE\n\n### Die Blumen Boutique\n\nProfessioneller Webauftritt für das Bottroper Fachgeschäft – mit klarer Leistungspräsentation, direkter Kundenführung und konsequenter Optimierung für lokale\nSichtbarkeit.\n\n[Projekt ansehen](https://www.dcpp-digital.de/?projekt=blumen-boutique) [Live-Webseite](https://www.die-blumen-boutique.de/)\n\nFEEDBACK AUS DER PRAXIS\n\nDie Inhaberin berichtet von merklich mehr Anfragen und Bestellungen über WhatsApp.\n\n[Kundenfeedback ansehen →](https://www.dcpp-digital.de/?projekt=blumen-boutique#dcpp-blumen-feedback)\n\nProjekt im Detail+\n\nAusgangslageDer bestehende Auftritt brauchte klarere Struktur, mobile Führung und bessere lokale Sichtbarkeit.\n\nUmsetzungResponsive Business-Webseite, sechs Floristikbereiche, direkte Kontaktwege, Maps sowie SEO/GEO-Bereinigung.\n\nErgebnisKlarer mobiler Auftritt, strukturierte Angebote und eine indexierbare Website mit direkten Kundenwegen.\n\nWeitere Webprojekte+\n\n[Bottroper Döner & Pizza Bottroper Döner & Pizza Webauftritt mit Speisekarte, Öffnungszeiten, Kontakt und direkter Routenführung. Projekt ansehen →](https://www.dcpp-digital.de/?projekt=bottroper-doener-pizza)\n\n[Logo Ristorante Pizzeria La Rosa Ristorante Pizzeria La RosaItalienisches Restaurant mit digitaler Speisekarte, Pizzataxi und direkter telefonischer Vorbestellung.Projekt ansehen](https://www.dcpp-digital.de/?projekt=ristorante-pizzeria-la-rosa) [Restaurant Olympia – Original-Geschäftslogo Restaurant OlympiaGriechisches Restaurant & Kegelbahn in Grafenwald. Webkonzept mit Speisekarte und direktem Kontakt.Projekt ansehen](https://www.dcpp-digital.de/?projekt=olympia-bottrop)\n\nAPP\n\n[3x3 HOME FIT](https://www.dcpp-digital.de/?projekt=3x3-home-fit)\n\nANDROIDTESTBUILD\n\n### 3x3 HOME FIT\n\nHome-Workout-App für Training auf kleinem Raum. Individuelle Workouts orientieren sich an Ziel, Fitnesslevel, verfügbarer Zeit, Platz und Equipment.\n\n[Projekt ansehen](https://www.dcpp-digital.de/?projekt=3x3-home-fit) [App ansehen](https://www.dcpp-digital.de/#3x3homefit)\n\nProjekt im Detail+\n\nAusgangslageTraining sollte ohne Studio und selbst auf sehr kleinem Raum sinnvoll planbar werden.\n\nUmsetzungApp-Konzept mit Onboarding nach Ziel, Fitnesslevel, Zeit, Platz und Equipment sowie Android-Testbuild.\n\nErgebnisFunktionsfähiger App-Prototyp mit klarer Trainingslogik und eigenständiger visueller Identität.\n\nWeitere App-Projekte+\n\n[FamilienKreis FamilienKreis Familien-App für Termine, Aufgaben, Einkäufe und den gemeinsamen Alltag. Projekt ansehen →](https://www.dcpp-digital.de/?projekt=familienkreis) [Kochheld Kochheld Kochideen aus deinem Vorrat – mit einfachen Rezepten und optionalen Fitnessfiltern. In Entwicklung. Projekt ansehen →](https://www.dcpp-digital.de/?projekt=kochheld) [HEY MALLE HEY MALLE Digitaler Playa-Begleiter vom Jachthafen in S’Arenal bis zum Balneario 15 in Can Pastilla. Projekt ansehen →](https://www.dcpp-digital.de/?projekt=hey-malle) [Release Buddy Release Buddy Musik-App für neue Singles, EPs und Alben mit Favoriten und Release Friday. Projekt ansehen →](https://www.dcpp-digital.de/?projekt=release-buddy) [Bratwurst mit mir Bratwurst mit mir Soziale App für Live-Aktivitäten, Freunde, Wurstzähler, Achievements und gemeinsame Runden. Projekt ansehen →](https://www.dcpp-digital.de/?projekt=bratwurst-mit-mir)\n\nCONTENT & BRAND\n\n[Sunny XXL Dogge](https://www.dcpp-digital.de/?projekt=sunny-xxl-dogge)\n\nLIVECONTENT\n\n### Sunny XXL Dogge\n\nEigenständige Content- und Webmarke rund um Sunny – mit hochwertigem Markenauftritt, Social-Media-Fokus und einer klaren visuellen Identität.\n\n[Projekt ansehen](https://www.dcpp-digital.de/?projekt=sunny-xxl-dogge) [Sunny ansehen](https://www.dcpp-digital.de/#sunnyxxl)\n\nProjekt im Detail+\n\nAusgangslageSocial-Content rund um Sunny sollte als eigenständige Marke sofort wiedererkennbar werden.\n\nUmsetzungBranding, Landingpage, Social-Struktur und eine kanalübergreifend konsistente visuelle Linie.\n\nErgebnisKonsistenter Content-Auftritt mit eigener Tonalität, Webpräsenz und klarem Social-Media-Fokus.\n\nWeitere Content-Projekte+\n\nWeitere Content-Projekte folgen. Neue Content- und Markenprojekte werden hier\nergänzt.\n\nDIGITAL-PUBLISHING\n\nDCPP DIGITAL\n\nPUBLISHING\n\nLIVEDIGITAL & PRINT\n\n### DCPP Digital Publishing\n\nEigenständig entwickelte Bücher und digitale Produkte – von Konzept, Inhalt und Gestaltung bis zur publikationsfähigen Ausgabe und direkten Produktdarstellung.\n\n[Portfolio ansehen](https://www.dcpp-digital.de/?projekt=digital-publishing) [Publishing anfragen](https://www.dcpp-digital.de/#dcpp-contact)\n\nProjekt im Detail+\n\nAusgangslageDigitale und gedruckte Produkte sollten nicht nur gestaltet, sondern veröffentlichungsfertig aufgebaut werden.\n\nUmsetzungKonzept, Layout, Produktdarstellung und Veröffentlichung – einschließlich eigener Buchprojekte.\n\nErgebnisEigenständiger Publishing-Bereich mit digitalen Produkten und veröffentlichten Printprojekten.\n\nPublishing im Überblick+\n\nDigitale ProduktePDF-Produkte, Workbooks und Erinnerungsbücher für Alltag, Familie und persönliche\nProjekte.\n\nPrint PublishingEigenständige Buch- und Kreativprojekte von der Konzeption bis zur\npublikationsfertigen Ausgabe.\n\nABLAUF\n\n## Von der Idee bis zur Veröffentlichung.\n\nVier klare Schritte sorgen dafür, dass aus einer Idee kein Technik-Chaos wird, sondern ein verständlich aufgebautes digitales Projekt.\n\n01\n\n### Ziel & Rahmen\n\nWas soll entstehen, für wen und warum? Ziel, Umfang und technische Möglichkeiten werden zuerst klar eingeordnet.\n\n02\n\n### Konzept & Design\n\nStruktur, Nutzerführung, Inhalte und visuelle Sprache werden passend zur Idee entwickelt – nicht aus einer Standardvorlage.\n\n03\n\n### Entwicklung & Test\n\nDie Lösung wird umgesetzt, responsiv geprüft und Schritt für Schritt auf Funktion, Verständlichkeit und Alltagstauglichkeit getestet.\n\n04\n\n### Veröffentlichung & Weiterentwicklung\n\nNach dem Go-live werden reale Nutzung, Sichtbarkeit und sinnvolle nächste Schritte weitergedacht – ohne unnötigen Technik-Hype.\n\n[Projekt besprechen](https://www.dcpp-digital.de/#dcpp-contact)\n\nDCPP PRINZIPIEN\n\n## Eine klare Linie – im Design und im Code.\n\nVier Grundsätze, die Gestaltung und technische Umsetzung zusammenhalten.\n\n### Klarheit vor Lautstärke.\n\nEine Oberfläche soll führen, nicht um Aufmerksamkeit kämpfen. Struktur, Hierarchie und Inhalt bleiben sofort erfassbar.\n\n### Funktion vor Effekt.\n\nBewegung, Farbe und Interaktion bekommen einen Zweck. Was gut aussieht, muss genauso sauber funktionieren.\n\n### Eigenständig statt Vorlage.\n\nJedes Projekt entwickelt eine eigene visuelle Sprache – passend zur Idee, statt austauschbar aus einem Standardraster.\n\n### Technik nach Bedarf. Nicht nach Hype.\n\nWerkzeuge werden eingesetzt, wenn sie das Produkt besser, schneller oder klarer machen – nicht weil sie gerade modern sind.\n\nHÄUFIGE FRAGEN\n\n## Kurz geklärt, bevor du anfragst.\n\nEine Idee muss noch nicht fertig sein. Entscheidend ist, was du erreichen möchtest – der passende Weg kann danach gemeinsam klar eingeordnet werden.\n\nWas kann DCPP Digital umsetzen?+\n\nWebseiten, Apps, Content- und Markenauftritte sowie Publishing-Projekte. Je nach Idee kann auch eine Kombination aus mehreren Bereichen sinnvoll sein.\n\nMuss meine Idee schon komplett fertig sein?+\n\nNein. Eine grobe Idee, ein Problem oder ein Ziel reicht als Startpunkt. Struktur, Umfang und technische Möglichkeiten werden anschließend Schritt für Schritt geklärt.\n\nKann DCPP auch bestehende Webseiten oder Projekte verbessern?+\n\nJa, wenn die technische Grundlage sinnvoll weiterverwendet werden kann. Vor Änderungen wird zuerst geprüft, was bleiben sollte und was wirklich verbessert werden muss.\n\nArbeitet DCPP nur in Bottrop?+\n\nNein. DCPP Digital hat seinen Standort in Bottrop, die Zusammenarbeit und Umsetzung kann digital auch deutschlandweit erfolgen.\n\nWie startet ein neues Projekt?+\n\nPer E-Mail, telefonisch oder per WhatsApp. Eine kurze Beschreibung deiner Idee, deines Ziels und – falls vorhanden – des aktuellen Stands reicht für den Einstieg.\n\nKONTAKT\n\n## Eine Idee im Kopf? Machen wir sie konkret.\n\nSchreib kurz, was du vorhast. Es muss noch kein fertiges Konzept sein – eine Idee, ein Ziel oder ein bestehender Stand reicht für den Einstieg.\n\n1 · Kurz anfragen Idee, Ziel und vorhandenen Stand beschreiben.\n\n2 · Rahmen klären Möglichkeiten, Umfang und sinnvollen nächsten Schritt einordnen.\n\n3 · Umsetzung planen Klare Empfehlung statt unnötiger Technik oder Funktionen.\n\nDIREKT STARTEN\n\n[@ E-Mail](mailto:kontakt@dcpp-digital.de?subject=DCPP%20Digital%20Projektanfrage)\n[☎ Anrufen](tel:+4920419862645) [WA WhatsApp](https://wa.me/message/M3USW7QBLDWYM1) [IG Instagram](https://www.instagram.com/dcpp_digital?stkn=a3RuZTdyeTByYXBr&utm_source=qr)\n[f Facebook](https://www.facebook.com/share/1HMDkUNQcK/?mibextid=wwXIfr) [in LinkedIn](https://www.linkedin.com/company/dcpp-digital/)\n\n[DCPP Digital Develop • Content • Create](https://www.dcpp-digital.de/#dcpp-start)\n\nWebdesign • Apps • Publishing aus Bottrop\n\n[Impressum](https://www.dcpp-digital.de/about/#dcpp-impressum-page) | [Datenschutz](https://www.dcpp-digital.de/j/privacy) |\n[Instagram](https://www.instagram.com/dcpp_digital?stkn=a3RuZTdyeTByYXBr&utm_source=qr) | [Facebook](https://www.facebook.com/share/1HMDkUNQcK/?mibextid=wwXIfr) | [WhatsApp](https://wa.me/message/M3USW7QBLDWYM1)\n\n© 2026 DCPP Digital • Develop • Content • Create\n"},"?projekt=ristorante-pizzeria-la-rosa":{"canonical":"https://www.dcpp-digital.de/?projekt=ristorante-pizzeria-la-rosa","markdown":"# Ristorante Pizzeria La Rosa – DCPP Digital\n\nEigenständiges Webkonzept für La Rosa Bottrop: Original-Speisekarte, persönlicher Bestellzettel, Pizzataxi, Öffnungszeiten und telefonische Vorbestellung.\n\nKanonische Projektadresse: https://www.dcpp-digital.de/?projekt=ristorante-pizzeria-la-rosa\n\n[DCPP Digital](https://www.dcpp-digital.de/#dcpp-start)[Alle Projekte](https://www.dcpp-digital.de/#dcpp-projects)\n\n[Leistungen](https://www.dcpp-digital.de/#dcpp-services)[Projekte](https://www.dcpp-digital.de/#dcpp-projects)[Kontakt](https://www.dcpp-digital.de/#dcpp-contact)\n\nPROJEKT · GASTRONOMIE · DESIGNKONZEPT\n\n# Ristorante Pizzeria La Rosa.\n\nEin Stück Italien in Bottrop. Ein eigenständiger Auftritt für Pizza, Pasta und Pizzataxi – mit vollständiger Speisekarte und direkter telefonischer Vorbestellung.\n\n[La-Rosa-Microsite ansehen](https://www.dcpp-digital.de/#larosabottrop)[Webprojekt anfragen](https://www.dcpp-digital.de/#dcpp-contact)\n\nLogo Ristorante Pizzeria La Rosa\n\nDAS ZIEL\n\n## Appetit wecken. Bestellung erleichtern.\n\nGäste finden Sortiment, Preise, Öffnungs- und Lieferzeiten an einem Ort. Klare Kontaktwege führen direkt zum Pizzataxi und zur telefonischen Vorbestellung. Adresse und\nRoutenplanung erleichtern den Besuch oder die Abholung an der Aegidistraße 111.\n\nDIE GESTALTUNG\n\n## La Rosa. Klar erkennbar.\n\nDer freigestellte La-Rosa-Schriftzug ist das Projektmotiv. Klare Weißflächen, Anthrazit und Tomatenrot treffen auf markante moderne Typografie. Die großflächige\nFotografie, die kompakte Speisekarte und ein persönlicher Bestellzettel prägen den eigenständigen Restaurantauftritt.\n\nDIE SPEISEKARTE\n\n## Eine Karte. Klare Auswahl.\n\nPizza, Nudeln, Salate und Gemüse, Getränke oder die Gesamtkarte lassen sich einzeln öffnen. Pasta-Unterbereiche, Suche nach Gerichtnummer oder Zutat und eine\nSeitennavigation erleichtern die Auswahl. Alle sechs Originalkartenseiten bleiben in einer kompakten Vorschau zum Durchblättern und in einer separaten Großansicht\nverfügbar. Ein Bestellzettel sammelt die Auswahl für den Anruf; Kontaktdatei und Standortfreigabe unterstützen den Besuch.\n\nPROJEKTSTATUS\n\n## Konzipiert und implementiert.\n\nEigenständig entwickeltes Gestaltungskonzept von DCPP Digital mit Originalfotos, vollständig übertragener Speisekarte, telefonischen Bestellwegen und belegten\nGoogle-Bewertungen mit Quellenstand. Die interaktive Vorschau ist die Grundlage für einen möglichen eigenen Restaurantauftritt.\n\n[La Rosa entdecken](https://www.dcpp-digital.de/#larosabottrop)[Zur Projektübersicht](https://www.dcpp-digital.de/#dcpp-projects)\n\nDCPP DIGITAL · WEBDESIGN\n\n## Eigene Website geplant?\n\nDCPP Digital erstellt individuelle Webseiten für Unternehmen und lokale Betriebe – passend zu Angebot, Zielgruppe und Arbeitsabläufen.\n\n[E-Mail](mailto:kontakt@dcpp-digital.de?subject=Webdesign-Anfrage) [Anrufen](tel:+4920419862645) [WhatsApp](https://wa.me/message/M3USW7QBLDWYM1)\n\n[DCPP Digital Develop • Content • Create](https://www.dcpp-digital.de/#dcpp-start)\n\n[Projekte](https://www.dcpp-digital.de/#dcpp-projects) [Kontakt](https://www.dcpp-digital.de/#dcpp-contact) [Impressum](https://www.dcpp-digital.de/about/#dcpp-impressum-page) [Datenschutz](https://www.dcpp-digital.de/j/privacy)\n\nEin Designkonzept von DCPP Digital.  ·  © 2026 DCPP Digital · Develop · Content · Create\n"},"?projekt=blumen-boutique":{"canonical":"https://www.dcpp-digital.de/?projekt=blumen-boutique","markdown":"# Die Blumen Boutique – DCPP Digital\n\nDie Blumen Boutique in Bottrop: responsives Webdesign, direkte WhatsApp-Kontaktwege und freigegebenes Kundenfeedback zu Bedienbarkeit und Anfragen.\n\nKanonische Projektadresse: https://www.dcpp-digital.de/?projekt=blumen-boutique\n\n[DCPP Digital](https://www.dcpp-digital.de/#dcpp-start) [← Zurück zu DCPP Digital ← DCPP](https://www.dcpp-digital.de/#dcpp-start)\n\n[Start](https://www.dcpp-digital.de/#dcpp-start) [Leistungen](https://www.dcpp-digital.de/#dcpp-services) [Projekte](https://www.dcpp-digital.de/#dcpp-projects) [Ablauf](https://www.dcpp-digital.de/#dcpp-process) [Kontakt](https://www.dcpp-digital.de/#dcpp-contact)\n\nPROJEKT · WEBDESIGN · BOTTROP\n\n# Die Blumen Boutique.\n\nProfessioneller Webauftritt für das Bottroper Fachgeschäft – mit klarer Leistungspräsentation, direkter Kundenführung und konsequenter Ausrichtung auf die mobile Nutzung.\n\n[Live-Webseite](https://www.die-blumen-boutique.de/) [Webdesign anfragen](https://www.dcpp-digital.de/#dcpp-contact)\n\nDie Blumen Boutique – Webdesign-Projekt von DCPP Digital\n\nBusiness-Webseite Responsive Lokale Nutzerführung Live in Bottrop\n\nAUSGANGSLAGE\n\n## Vorhandene Inhalte klarer führen.\n\nDer bestehende Auftritt enthielt die wichtigen Informationen des Fachgeschäfts, brauchte aber eine klarere visuelle Hierarchie, eine bessere mobile Führung und eine\nübersichtlichere Präsentation der Floristikangebote.\n\nZIEL\n\n## Schneller zu Angebot und Kontakt.\n\nÖffnungszeiten, Route, Kontakt und Leistungen sollten früher sichtbar werden. Gleichzeitig sollte die Website den persönlichen Charakter des Geschäfts behalten und auf\nSmartphone wie Desktop sauber funktionieren.\n\nUMSETZUNG\n\n## Struktur statt Umwege.\n\nKlare Seitenstruktur Besuchsinformationen, Leistungen und Kontaktwege nach Nutzerpriorität geordnet.\n\nFloristikbereiche Sträuße, Brautfloristik, Tischdekoration, Raum- & Kirchenschmuck, Trauerfloristik sowie Pflanzen & Dekoration\neinheitlich aufgebaut.\n\nDirekte Kontaktwege Anruf, WhatsApp, Anfrage und Route ohne unnötige Zwischenschritte erreichbar.\n\nResponsive Umsetzung Darstellung und Bedienung konsequent für Desktop und Smartphone abgestimmt.\n\nERGEBNIS\n\n## Ruhiger Auftritt. Klare Wege.\n\nDie fertige Website verbindet die Markenwirkung des Fachgeschäfts mit einer deutlich geordneten Nutzerführung. Leistungen sind schneller erfassbar, Kontaktmöglichkeiten\nliegen näher am Bedarf und die mobile Darstellung bleibt übersichtlich.\n\n[Website ansehen](https://www.die-blumen-boutique.de/) [Webdesign anfragen](https://www.dcpp-digital.de/#dcpp-contact)\n\nKUNDENREFERENZ · BOTTROP\n\n## Feedback aus der Praxis.\n\nEntscheidend ist nicht nur, wie eine Website aussieht, sondern wie gut sie im Geschäftsalltag funktioniert.\n\nRÜCKMELDUNG DER INHABERIN\n\nSeit der Neugestaltung werden nach Angaben der Inhaberin merklich mehr Anfragen und Bestellungen über WhatsApp abgewickelt.\n\nAuch aus der Kundschaft gibt es positives Feedback: Gelobt werden die einfache Handhabung, die stimmige Gestaltung und die verständliche Darstellung des vielseitigen\nFloristikangebots.\n\nTP Tanja PretzerInhaberin · Die Blumen Boutique, Bottrop\n\n01\n\n### Direkter Kundenkontakt\n\nWhatsApp erleichtert den Weg von der ersten Frage zur konkreten Bestellung.\n\n02\n\n### Einfach zu bedienen\n\nDie klare Nutzerführung hilft Interessierten, schnell zum passenden Angebot zu finden.\n\n03\n\n### Floristik verständlich präsentiert\n\nLeistungsbereiche und Gestaltung machen das Angebot des Fachgeschäfts nachvollziehbar.\n\n[Die fertige Website besuchen ↗](https://www.die-blumen-boutique.de/)\n\nFreigegebene, sinngemäße Zusammenfassung des Kundenfeedbacks. Die berichtete Entwicklung ist nicht als unabhängig gemessene Kennzahl ausgewiesen.\n\nDCPP DIGITAL · WEBDESIGN\n\n## Auch eine Website geplant?\n\nFür lokale Unternehmen, Selbstständige und kleine Betriebe – klar strukturiert, responsiv und passend zum tatsächlichen Geschäftsziel.\n\n[E-Mail](mailto:kontakt@dcpp-digital.de?subject=Webdesign-Anfrage) [Anrufen](tel:+4920419862645) [WhatsApp](https://wa.me/message/M3USW7QBLDWYM1)\n\n[DCPP Digital Develop • Content • Create](https://www.dcpp-digital.de/#dcpp-start)\n\n[Projekte](https://www.dcpp-digital.de/#dcpp-projects) [Kontakt](https://www.dcpp-digital.de/#dcpp-contact) [Impressum](https://www.dcpp-digital.de/about/#dcpp-impressum-page) [Datenschutz](https://www.dcpp-digital.de/j/privacy)\n\n© 2026 DCPP Digital · Develop • Content • Create\n"},"?projekt=3x3-home-fit":{"canonical":"https://www.dcpp-digital.de/?projekt=3x3-home-fit","markdown":"# 3x3 HOME FIT – DCPP Digital\n\n3x3 HOME FIT ist eine Home-Workout-App von DCPP Digital für Training auf kleinem Raum – abgestimmt auf Zeit, Ziel, Fitnesslevel und Equipment.\n\nKanonische Projektadresse: https://www.dcpp-digital.de/?projekt=3x3-home-fit\n\n[DCPP Digital](https://www.dcpp-digital.de/#dcpp-start) [← Zurück zu DCPP Digital ← DCPP](https://www.dcpp-digital.de/#dcpp-start)\n\n[Start](https://www.dcpp-digital.de/#dcpp-start) [Leistungen](https://www.dcpp-digital.de/#dcpp-services) [Projekte](https://www.dcpp-digital.de/#dcpp-projects) [Ablauf](https://www.dcpp-digital.de/#dcpp-process) [Kontakt](https://www.dcpp-digital.de/#dcpp-contact)\n\nPROJEKT · APP-ENTWICKLUNG · ANDROID\n\n# 3x3 HOME FIT.\n\nHome-Workout-App für Training auf kleinem Raum – persönliche Workouts nach Zeit, Platz, Ausrüstung, Fitnesslevel, Ziel und Tagesform.\n\n[App ansehen](https://www.dcpp-digital.de/#3x3homefit) [Test-APK](https://github.com/Bratwurstmitmir/3x3-home-fit/releases/download/v1.0.2/3x3-home-fit-1.0.2.apk)\n\n3x3 HOME FIT – App-Projekt von DCPP Digital\n\nAndroid-Testbuild Home-Workout Individuelle Trainings DCPP App\n\nAUSGANGSLAGE\n\n## Training muss zum Alltag passen.\n\nWenig Zeit, wenig Platz oder kein Fitnessstudio sollten kein Hindernis sein. Das Projekt brauchte deshalb eine Trainingslogik, die sich an den tatsächlichen Möglichkeiten\ndes Tages orientiert.\n\nZIEL\n\n## Wenige Angaben. Passendes Training.\n\nStatt komplizierter Pläne sollte die App aus Ziel, Fitnesslevel, Zeit, Platz, Ausrüstung und Tagesform ein direkt nutzbares Workout zusammenstellen.\n\nUMSETZUNG\n\n## Persönlich statt pauschal.\n\nTraining nach Alltag Zeit, verfügbarer Platz und vorhandene Ausrüstung fließen direkt in die Zusammenstellung ein.\n\nFitnesslevel & Ziel Trainingsauswahl und Belastung orientieren sich am persönlichen Ausgangspunkt und Trainingsziel.\n\nTagesform Das Training kann an einen entspannten, normalen oder besonders energiegeladenen Tag angepasst werden.\n\nFortschritt & Motivation Favoriten, gespeicherte Trainings, Ziele und soziale Funktionen ergänzen die eigentliche Trainingslogik.\n\nERGEBNIS\n\n## Ein klarer Android-Testbuild.\n\nEntstanden ist ein funktionsfähiger App-Prototyp mit eigenständiger visueller Identität und einer Trainingslogik, die kleine Räume und reale Alltagssituationen bewusst\nmitdenkt.\n\n[GitHub Release](https://github.com/Bratwurstmitmir/3x3-home-fit/releases/tag/v1.0.2)\n[App anfragen](https://www.dcpp-digital.de/#dcpp-contact)\n\nDCPP DIGITAL · APP-ENTWICKLUNG\n\n## Eigene App-Idee geplant?\n\nVon der Funktionsidee über UX/UI bis zum klar abgegrenzten Testbuild – verständlich aufgebaut und Schritt für Schritt entwickelt.\n\n[E-Mail](mailto:kontakt@dcpp-digital.de?subject=3x3%20HOME%20FIT%20Anfrage) [Anrufen](tel:+4920419862645) [WhatsApp](https://wa.me/message/M3USW7QBLDWYM1)\n\n[DCPP Digital Develop • Content • Create](https://www.dcpp-digital.de/#dcpp-start)\n\n[Projekte](https://www.dcpp-digital.de/#dcpp-projects) [Kontakt](https://www.dcpp-digital.de/#dcpp-contact) [Impressum](https://www.dcpp-digital.de/about/#dcpp-impressum-page) [Datenschutz](https://www.dcpp-digital.de/j/privacy)\n\n© 2026 DCPP Digital · Develop • Content • Create\n"},"?projekt=sunny-xxl-dogge":{"canonical":"https://www.dcpp-digital.de/?projekt=sunny-xxl-dogge","markdown":"# Sunny XXL Dogge – DCPP Digital\n\nSunny XXL Dogge ist ein Content- und Branding-Projekt von DCPP Digital mit Webauftritt, Social-Media-Struktur und klarer visueller Markenwelt.\n\nKanonische Projektadresse: https://www.dcpp-digital.de/?projekt=sunny-xxl-dogge\n\n[DCPP Digital](https://www.dcpp-digital.de/#dcpp-start) [← Zurück zu DCPP Digital ← DCPP](https://www.dcpp-digital.de/#dcpp-start)\n\n[Start](https://www.dcpp-digital.de/#dcpp-start) [Leistungen](https://www.dcpp-digital.de/#dcpp-services) [Projekte](https://www.dcpp-digital.de/#dcpp-projects) [Ablauf](https://www.dcpp-digital.de/#dcpp-process) [Kontakt](https://www.dcpp-digital.de/#dcpp-contact)\n\nPROJEKT · CONTENT & BRAND · SOCIAL\n\n# Sunny XXL Dogge.\n\nEigenständige Content- und Webmarke rund um Sunny – mit wiedererkennbarem Markenauftritt, Social-Media-Fokus und einer klaren visuellen Identität.\n\n[Sunny ansehen](https://www.dcpp-digital.de/#sunnyxxl) [Instagram](https://www.instagram.com/sunnyxxldogge?stkn=eXdvOG52Y2Fiams1&utm_source=qr)\n\nSunny XXL Dogge – Content- und Brand-Projekt von DCPP Digital\n\nContent & Brand Social Media Webauftritt Live\n\nAUSGANGSLAGE\n\n## Viele Momente. Eine erkennbare Marke.\n\nFotos, Videos und Alltag rund um Sunny sollten nicht wie einzelne Beiträge nebeneinanderstehen, sondern als zusammenhängende Marke sofort wiedererkennbar werden.\n\nZIEL\n\n## Ein Auftritt mit eigener Persönlichkeit.\n\nWebseite und Social-Media-Kanäle sollten dieselbe Bildwelt, Tonalität und Markenlogik tragen – persönlich, klar und ohne den echten Doggenalltag künstlich zu inszenieren.\n\nUMSETZUNG\n\n## Eine Linie über alle Kanäle.\n\nBranding Logo, Typografie, Bildsprache und wiederkehrende Gestaltungselemente bilden einen konsistenten Markenrahmen.\n\nWebpräsenz Der Webauftritt bündelt Sunny, Herkunft, Alltag, Motive und Social-Kanäle in einer klaren Struktur.\n\nSocial-Struktur Instagram, TikTok und Facebook werden als zusammengehörige Kanäle statt als getrennte Einzelauftritte gedacht.\n\nContent-Formate Alltag, Abenteuer, Entwicklung und typische Sunny-Momente erhalten wiedererkennbare inhaltliche Formate.\n\nERGEBNIS\n\n## Wiedererkennung statt Einzelposts.\n\nSunny XXL Dogge funktioniert als eigenständige Content-Marke mit konsistenter visueller Linie, klarer Webpräsenz und direkter Verbindung zu den Social-Media-Kanälen.\n\n[Sunny auf Instagram](https://www.instagram.com/sunnyxxldogge?stkn=eXdvOG52Y2Fiams1&utm_source=qr) [Content anfragen](https://www.dcpp-digital.de/#dcpp-contact)\n\nDCPP DIGITAL · CONTENT & BRAND\n\n## Eigene Content-Marke geplant?\n\nVon der visuellen Linie bis zum Webauftritt – für Projekte, die über mehrere Kanäle hinweg wiedererkennbar bleiben sollen.\n\n[E-Mail](mailto:kontakt@dcpp-digital.de?subject=Sunny%20XXL%20Dogge%20Anfrage) [Anrufen](tel:+4920419862645) [WhatsApp](https://wa.me/message/M3USW7QBLDWYM1)\n\n[DCPP Digital Develop • Content • Create](https://www.dcpp-digital.de/#dcpp-start)\n\n[Projekte](https://www.dcpp-digital.de/#dcpp-projects) [Kontakt](https://www.dcpp-digital.de/#dcpp-contact) [Impressum](https://www.dcpp-digital.de/about/#dcpp-impressum-page) [Datenschutz](https://www.dcpp-digital.de/j/privacy)\n\n© 2026 DCPP Digital · Develop • Content • Create\n"},"?projekt=familienkreis":{"canonical":"https://www.dcpp-digital.de/?projekt=familienkreis","markdown":"# FamilienKreis – DCPP Digital\n\nFamilienKreis ist eine Familien-App von DCPP Digital für Termine, Aufgaben, Einkäufe, Essen, Menschen, Haustiere und gemeinsame Alltagsplanung.\n\nKanonische Projektadresse: https://www.dcpp-digital.de/?projekt=familienkreis\n\n[DCPP Digital](https://www.dcpp-digital.de/#dcpp-start) [← Zurück zu DCPP Digital ← DCPP](https://www.dcpp-digital.de/#dcpp-start)\n\n[Start](https://www.dcpp-digital.de/#dcpp-start) [Leistungen](https://www.dcpp-digital.de/#dcpp-services) [Projekte](https://www.dcpp-digital.de/#dcpp-projects) [Ablauf](https://www.dcpp-digital.de/#dcpp-process) [Kontakt](https://www.dcpp-digital.de/#dcpp-contact)\n\nPROJEKT · APP-ENTWICKLUNG · IN ENTWICKLUNG\n\n# FamilienKreis.\n\nFamilien-App für Termine, Aufgaben, Einkauf, Essen, Menschen, Haustiere und gemeinsame Planung – gebündelt in einer übersichtlichen Struktur.\n\n[App ansehen](https://www.dcpp-digital.de/#familienkreis) [App anfragen](https://www.dcpp-digital.de/#dcpp-contact)\n\nFamilienKreis – App-Projekt von DCPP Digital\n\nFamilien-App Gemeinsame Planung Menschen & Haustiere In Entwicklung\n\nAUSGANGSLAGE\n\n## Familienalltag verteilt sich auf viele Orte.\n\nTermine, Aufgaben, Einkaufswünsche, Essensplanung und Haustier-Themen landen schnell in verschiedenen Chats, Kalendern und Notizen. Dadurch fehlt eine gemeinsame\nÜbersicht.\n\nZIEL\n\n## Ein gemeinsamer Ort für den Alltag.\n\nFamilienKreis soll die wichtigsten Bereiche des Familienlebens bündeln, Personen klar zuordnen und später auch mehrere Kreise miteinander verbinden können.\n\nUMSETZUNG\n\n## Gemeinsam organisiert.\n\nKalender Gemeinsame Termine werden Personen zugeordnet und können mit Erinnerungen ergänzt werden.\n\nAufgaben & Einkauf Aufgaben, Einkaufswünsche und Listen werden zentral gesammelt und gemeinsam gepflegt.\n\nEssen & Wünsche Essensideen und Wünsche erhalten einen eigenen Platz statt in einzelnen Nachrichten zu verschwinden.\n\nMenschen, Haustiere & Kreise Mitglieder, Haustiere und die geplante Verbindung mehrerer FamilienKreise sind Teil der Produktlogik.\n\nERGEBNIS\n\n## Eine klare Produktstruktur für Familie.\n\nDas Projekt besitzt eine ausgearbeitete Marken- und App-Struktur, die zentrale Alltagsthemen zusammenführt. FamilienKreis befindet sich weiterhin in Entwicklung und wird\nschrittweise ausgebaut.\n\n[App anfragen](https://www.dcpp-digital.de/#dcpp-contact) [E-Mail](mailto:kontakt@dcpp-digital.de?subject=FamilienKreis%20oder%20App-Anfrage)\n\nDCPP DIGITAL · APP-ENTWICKLUNG\n\n## Eine App-Idee im Kopf?\n\nDCPP strukturiert Funktionen, Nutzerwege und Oberfläche so, dass aus einer Idee ein nachvollziehbares digitales Produkt werden kann.\n\n[E-Mail](mailto:kontakt@dcpp-digital.de?subject=FamilienKreis%20Anfrage) [Anrufen](tel:+4920419862645) [WhatsApp](https://wa.me/message/M3USW7QBLDWYM1)\n\n[DCPP Digital Develop • Content • Create](https://www.dcpp-digital.de/#dcpp-start)\n\n[Projekte](https://www.dcpp-digital.de/#dcpp-projects) [Kontakt](https://www.dcpp-digital.de/#dcpp-contact) [Impressum](https://www.dcpp-digital.de/about/#dcpp-impressum-page) [Datenschutz](https://www.dcpp-digital.de/j/privacy)\n\n© 2026 DCPP Digital · Develop • Content • Create\n"},"?projekt=hey-malle":{"canonical":"https://www.dcpp-digital.de/?projekt=hey-malle","markdown":"# HEY MALLE – DCPP Digital\n\nHEY MALLE ist eine Playa-de-Palma-App von DCPP Digital mit Wetter, Hotspots, Events, Freunden, Check-ins und Routen für den mobilen Einsatz.\n\nKanonische Projektadresse: https://www.dcpp-digital.de/?projekt=hey-malle\n\n[DCPP Digital](https://www.dcpp-digital.de/#dcpp-start) [← Zurück zu DCPP Digital ← DCPP](https://www.dcpp-digital.de/#dcpp-start)\n\n[Start](https://www.dcpp-digital.de/#dcpp-start) [Leistungen](https://www.dcpp-digital.de/#dcpp-services) [Projekte](https://www.dcpp-digital.de/#dcpp-projects) [Ablauf](https://www.dcpp-digital.de/#dcpp-process) [Kontakt](https://www.dcpp-digital.de/#dcpp-contact)\n\nPROJEKT · APP-ENTWICKLUNG · PLAYA DE PALMA\n\n# HEY MALLE.\n\nDigitaler Begleiter für die Playa de Palma – mit Wetter, Hotspots, Events, Freunden, Check-ins, Favoriten, Preisen und Routen.\n\n[App ansehen](https://www.dcpp-digital.de/#heymalle) [App anfragen](https://www.dcpp-digital.de/#dcpp-contact)\n\nHEY MALLE – App-Projekt von DCPP Digital\n\nPlaya de Palma Wetter & Hotspots Freunde & Events Android geplant\n\nAUSGANGSLAGE\n\n## Vor Ort zählt schnelle Orientierung.\n\nAn der Playa wechseln Wetter, Treffpunkte, Events und Pläne schnell. Informationen liegen oft verteilt, obwohl Nutzer unterwegs möglichst wenig suchen wollen.\n\nZIEL\n\n## Öffnen. Sehen, was gerade wichtig ist.\n\nHEY MALLE soll Wetter, Orte, Events, Freunde und Routen in einer mobilen Oberfläche bündeln und damit als unkomplizierter Begleiter vor Ort funktionieren.\n\nUMSETZUNG\n\n## Playa-Informationen an einem Ort.\n\nLive-Wetter Temperatur, Wetterlage, Wind und weitere Tagesinformationen sind als zentraler Einstieg vorgesehen.\n\nHotspots & Zonen Bars, Clubs, Restaurants, Strandpunkte und Playa-Bereiche werden nach Relevanz und Entfernung strukturiert.\n\nFreunde & Check-ins Freunde, Treffpunkte und Check-ins sollen zeigen, wer gerade wo unterwegs ist.\n\nEvents & Routen Veranstaltungen, Uhrzeiten, Locations und direkte Routen ergänzen den mobilen Begleiter.\n\nERGEBNIS\n\n## Ein klar ausgearbeitetes App-Konzept.\n\nHEY MALLE besitzt eine eigenständige Markenwelt und eine strukturierte App-Idee für den Einsatz vor Ort. Die Android-Testversion ist als nächster Entwicklungsschritt\nvorgesehen.\n\n[App anfragen](https://www.dcpp-digital.de/#dcpp-contact) [E-Mail](mailto:kontakt@dcpp-digital.de?subject=HEY%20MALLE%20oder%20App-Anfrage)\n\nDCPP DIGITAL · APP-ENTWICKLUNG\n\n## Aus einer Idee soll eine App werden?\n\nDCPP entwickelt Funktionsumfang, UX/UI und technische Umsetzung in klaren Schritten – vom Konzept bis zum Testbuild.\n\n[E-Mail](mailto:kontakt@dcpp-digital.de?subject=HEY%20MALLE%20Anfrage) [Anrufen](tel:+4920419862645) [WhatsApp](https://wa.me/message/M3USW7QBLDWYM1)\n\n[DCPP Digital Develop • Content • Create](https://www.dcpp-digital.de/#dcpp-start)\n\n[Projekte](https://www.dcpp-digital.de/#dcpp-projects) [Kontakt](https://www.dcpp-digital.de/#dcpp-contact) [Impressum](https://www.dcpp-digital.de/about/#dcpp-impressum-page) [Datenschutz](https://www.dcpp-digital.de/j/privacy)\n\n© 2026 DCPP Digital · Develop • Content • Create\n"},"?projekt=release-buddy":{"canonical":"https://www.dcpp-digital.de/?projekt=release-buddy","markdown":"# Release Buddy – DCPP Digital\n\nRelease Buddy ist eine App von DCPP Digital für neue Singles, EPs und Alben – mit Lieblingskünstlern, Genres, Favoriten und Release Friday.\n\nKanonische Projektadresse: https://www.dcpp-digital.de/?projekt=release-buddy\n\n[DCPP Digital](https://www.dcpp-digital.de/#dcpp-start) [← Zurück zu DCPP Digital ← DCPP](https://www.dcpp-digital.de/#dcpp-start)\n\n[Start](https://www.dcpp-digital.de/#dcpp-start) [Leistungen](https://www.dcpp-digital.de/#dcpp-services) [Projekte](https://www.dcpp-digital.de/#dcpp-projects) [Ablauf](https://www.dcpp-digital.de/#dcpp-process) [Kontakt](https://www.dcpp-digital.de/#dcpp-contact)\n\nPROJEKT · APP-ENTWICKLUNG · MUSIK\n\n# Release Buddy.\n\nMusik-App für neue Singles, EPs und Alben – mit Lieblingskünstlern, Genres, Favoriten und einem klaren Fokus auf neue Veröffentlichungen.\n\n[App ansehen](https://www.dcpp-digital.de/#releasebuddy) [App anfragen](https://www.dcpp-digital.de/#dcpp-contact)\n\nRelease Buddy – App-Projekt von DCPP Digital\n\nMusik-App Neue Releases Favoriten Release Friday\n\nAUSGANGSLAGE\n\n## Neue Musik ist schnell unübersichtlich.\n\nNeuerscheinungen verteilen sich über viele Künstler, Genres und Plattformen. Wer regelmäßig neue Musik entdecken will, muss Informationen oft selbst zusammensuchen.\n\nZIEL\n\n## Neue Releases schneller im Blick.\n\nRelease Buddy soll Singles, EPs und Alben bündeln und die Übersicht nach Lieblingskünstlern und Genres persönlich relevanter machen – ohne einen eigenen Musikplayer zu\nbauen.\n\nUMSETZUNG\n\n## Entdecken statt durchsuchen.\n\nNeue Releases Veröffentlichungen werden nach aktuell, diese Woche und demnächst strukturiert.\n\nLieblingskünstler Ausgewählte Künstler können in der persönlichen Übersicht priorisiert werden.\n\nGenres & Favoriten Musikrichtungen und lokal gespeicherte Favoriten helfen beim schnellen Wiederfinden.\n\nRelease Friday Der Freitag wird als wiederkehrender Moment für neue Musik in der Produktidee verankert.\n\nERGEBNIS\n\n## Eine fokussierte Musik-App-Idee.\n\nRelease Buddy verbindet eine klare Markenwelt mit einem verständlichen Produktkonzept für Neuerscheinungen. Die App bleibt bewusst auf Entdecken, Merken und externe\nMusikdienste konzentriert.\n\n[App anfragen](https://www.dcpp-digital.de/#dcpp-contact) [E-Mail](mailto:kontakt@dcpp-digital.de?subject=Release%20Buddy%20oder%20App-Anfrage)\n\nDCPP DIGITAL · APP-ENTWICKLUNG\n\n## Eine fokussierte App statt Funktionschaos?\n\nDCPP priorisiert den Kernnutzen und baut daraus ein verständliches Produkt mit klaren Nutzerwegen und eigenständiger Oberfläche.\n\n[E-Mail](mailto:kontakt@dcpp-digital.de?subject=Release%20Buddy%20Anfrage) [Anrufen](tel:+4920419862645) [WhatsApp](https://wa.me/message/M3USW7QBLDWYM1)\n\n[DCPP Digital Develop • Content • Create](https://www.dcpp-digital.de/#dcpp-start)\n\n[Projekte](https://www.dcpp-digital.de/#dcpp-projects) [Kontakt](https://www.dcpp-digital.de/#dcpp-contact) [Impressum](https://www.dcpp-digital.de/about/#dcpp-impressum-page) [Datenschutz](https://www.dcpp-digital.de/j/privacy)\n\n© 2026 DCPP Digital · Develop • Content • Create\n"},"?projekt=bottroper-doener-pizza":{"canonical":"https://www.dcpp-digital.de/?projekt=bottroper-doener-pizza","markdown":"# Bottroper Döner & Pizza – DCPP Digital\n\nWebdesign-Konzept von DCPP Digital für Bottroper Döner & Pizza: Speisekarte, Öffnungszeiten, Kontakt, Bewertungen und direkte Routenführung.\n\nKanonische Projektadresse: https://www.dcpp-digital.de/?projekt=bottroper-doener-pizza\n\n[DCPP Digital](https://www.dcpp-digital.de/#dcpp-start) [← Zurück zu DCPP Digital ← DCPP](https://www.dcpp-digital.de/#dcpp-start)\n\n[Start](https://www.dcpp-digital.de/#dcpp-start) [Leistungen](https://www.dcpp-digital.de/#dcpp-services) [Projekte](https://www.dcpp-digital.de/#dcpp-projects) [Ablauf](https://www.dcpp-digital.de/#dcpp-process) [Kontakt](https://www.dcpp-digital.de/#dcpp-contact)\n\nPROJEKT · WEBDESIGN · BOTTROP-EIGEN\n\n# Bottroper Döner & Pizza.\n\nProof-of-Concept-Webauftritt für einen lokalen Gastronomiebetrieb – mit Speisekarte, Öffnungszeiten, Kontakt, Bewertungen und direkter Routenführung.\n\n[Webseite ansehen](https://www.dcpp-digital.de/#bottroperdoener) [Webdesign anfragen](https://www.dcpp-digital.de/#dcpp-contact)\n\nBottroper Döner und Pizza – Webdesign-Projekt von DCPP Digital\n\nWebdesign-Konzept Gastronomie Speisekarte & Kontakt Bottrop-Eigen\n\nAUSGANGSLAGE\n\n## Viele Informationen müssen mobil sofort sitzen.\n\nBei einem lokalen Gastronomie-Auftritt zählen Speisekarte, Öffnungszeiten, Standort und Kontakt stärker als lange Image-Texte. Genau diese Informationen müssen unterwegs\nschnell erreichbar sein.\n\nZIEL\n\n## Hunger ohne Umwege in Handlung übersetzen.\n\nDer Webauftritt sollte Angebot, Anruf, Route und Öffnungszeiten klar priorisieren und gleichzeitig einen eigenständigen lokalen Markencharakter zeigen.\n\nUMSETZUNG\n\n## Lokal, direkt und mobil gedacht.\n\nSpeisekarte Angebot und Original-Speisekarten werden übersichtlich und mobil erreichbar eingebunden.\n\nÖffnungszeiten & Standort Adresse, Öffnungszeiten und Routenführung stehen dort, wo Nutzer sie tatsächlich brauchen.\n\nKontakt Telefon und direkte Aktionen reduzieren unnötige Suchwege.\n\nBewertungen & Social Bewertungen sowie Social-Kanäle ergänzen den lokalen Vertrauensaufbau.\n\nERGEBNIS\n\n## Ein vollständiger Proof of Concept.\n\nEntstanden ist ein durchgängiger Gastronomie-Webauftritt als Proof of Concept: mobil nutzbar, lokal ausgerichtet und mit den wichtigsten Kundenwegen direkt im Vordergrund.\n\n[Route öffnen](https://www.google.com/maps/dir/?api=1&destination=Kirchhellener+Str.+270,+46240+Bottrop) [Webdesign anfragen](https://www.dcpp-digital.de/#dcpp-contact)\n\nDCPP DIGITAL · WEBDESIGN\n\n## Lokales Geschäft besser digital führen?\n\nDCPP strukturiert lokale Webseiten so, dass Angebot, Kontakt, Standort und mobile Nutzung klar zusammenarbeiten.\n\n[E-Mail](mailto:kontakt@dcpp-digital.de?subject=Bottroper%20D%C3%B6ner%20%26%20Pizza%20Anfrage) [Anrufen](tel:+4920419862645) [WhatsApp](https://wa.me/message/M3USW7QBLDWYM1)\n\n[DCPP Digital Develop • Content • Create](https://www.dcpp-digital.de/#dcpp-start)\n\n[Projekte](https://www.dcpp-digital.de/#dcpp-projects) [Kontakt](https://www.dcpp-digital.de/#dcpp-contact) [Impressum](https://www.dcpp-digital.de/about/#dcpp-impressum-page) [Datenschutz](https://www.dcpp-digital.de/j/privacy)\n\n© 2026 DCPP Digital · Develop • Content • Create\n"},"?projekt=bratwurst-mit-mir":{"canonical":"https://www.dcpp-digital.de/?projekt=bratwurst-mit-mir","markdown":"# Bratwurst mit mir – DCPP Digital\n\nBratwurst mit mir ist eine soziale App von DCPP Digital mit Live-Status, Freunden, Wurstzähler, Reaktionen, Achievements und Android-Testversion.\n\nKanonische Projektadresse: https://www.dcpp-digital.de/?projekt=bratwurst-mit-mir\n\n[DCPP Digital](https://www.dcpp-digital.de/#dcpp-start) [← Zurück zu DCPP Digital ← DCPP](https://www.dcpp-digital.de/#dcpp-start)\n\n[Start](https://www.dcpp-digital.de/#dcpp-start) [Leistungen](https://www.dcpp-digital.de/#dcpp-services) [Projekte](https://www.dcpp-digital.de/#dcpp-projects) [Ablauf](https://www.dcpp-digital.de/#dcpp-process) [Kontakt](https://www.dcpp-digital.de/#dcpp-contact)\n\nPROJEKT · APP-ENTWICKLUNG · SOCIAL\n\n# Bratwurst mit mir.\n\nSoziale Bratwurst-App für Live-Aktivitäten, Freunde, Wurstzähler, Reaktionen, Achievements und gemeinsame Bratwurst-Runden.\n\n[App ansehen](https://www.dcpp-digital.de/#bratwurstmitmir) [Android APK](https://github.com/Bratwurstmitmir/bratwurst-mit-mir/releases/download/v1.0.4/app-release.apk)\n\nBratwurst mit mir – App-Projekt von DCPP Digital\n\nAndroid-Testversion Freunde Live-Status Achievements\n\nAUSGANGSLAGE\n\n## Eine einfache Idee braucht soziale Dynamik.\n\nDie Grundidee ist bewusst leicht: zeigen, wenn gerade eine Bratwurst gegessen wird. Daraus sollte eine kleine soziale App mit Zähler, Freunden und gemeinsamen Momenten\nentstehen.\n\nZIEL\n\n## Schnell teilen. Gemeinsam zählen.\n\nDie App sollte ohne Standortzwang funktionieren und Live-Status, Freundesverbindungen und persönliche Statistiken in einem unkomplizierten Ablauf zusammenführen.\n\nUMSETZUNG\n\n## Sozialer Kern mit Wurstfaktor.\n\nLive-Status Nutzer können zeigen, wenn sie gerade an der Wurst sind.\n\nFreunde Freundescodes verbinden Profile und machen Aktivitäten untereinander sichtbar.\n\nZähler & Statistiken Abgeschlossene Bratwürste, Varianten und persönliche Werte werden im Profil gesammelt.\n\nAchievements & Runden Erfolge, Reaktionen und gemeinsame Bratwurst-Runden erweitern die soziale Idee.\n\nERGEBNIS\n\n## Eine funktionierende Android-Testversion.\n\nDas Projekt verbindet bewusst humorvolle Marke und echte App-Funktionen. Die Android-Testversion bildet den sozialen Kern mit Freunden, Live-Status, Zähler und\nAchievements ab.\n\n[Android APK](https://github.com/Bratwurstmitmir/bratwurst-mit-mir/releases/download/v1.0.4/app-release.apk) [App anfragen](https://www.dcpp-digital.de/#dcpp-contact)\n\nDCPP DIGITAL · APP-ENTWICKLUNG\n\n## Ungewöhnliche App-Idee? Umso besser.\n\nDCPP bringt auch ungewöhnliche Konzepte in eine klare Funktionsstruktur – mit Fokus auf den Kernnutzen statt auf unnötige Komplexität.\n\n[E-Mail](mailto:kontakt@dcpp-digital.de?subject=Bratwurst%20mit%20mir%20Anfrage) [Anrufen](tel:+4920419862645) [WhatsApp](https://wa.me/message/M3USW7QBLDWYM1)\n\n[DCPP Digital Develop • Content • Create](https://www.dcpp-digital.de/#dcpp-start)\n\n[Projekte](https://www.dcpp-digital.de/#dcpp-projects) [Kontakt](https://www.dcpp-digital.de/#dcpp-contact) [Impressum](https://www.dcpp-digital.de/about/#dcpp-impressum-page) [Datenschutz](https://www.dcpp-digital.de/j/privacy)\n\n© 2026 DCPP Digital · Develop • Content • Create\n"},"?projekt=kochheld":{"canonical":"https://www.dcpp-digital.de/?projekt=kochheld","markdown":"# Kochheld – DCPP Digital\n\nKochheld ist eine Koch-App von DCPP Digital für Rezeptideen aus vorhandenen Zutaten – mit Einkaufshilfe, Favoriten und einfacher Vorratsnutzung.\n\nKanonische Projektadresse: https://www.dcpp-digital.de/?projekt=kochheld\n\n[DCPP Digital](https://www.dcpp-digital.de/#dcpp-start) [← Zurück zu DCPP Digital ← DCPP](https://www.dcpp-digital.de/#dcpp-start)\n\n[Start](https://www.dcpp-digital.de/#dcpp-start) [Leistungen](https://www.dcpp-digital.de/#dcpp-services) [Projekte](https://www.dcpp-digital.de/#dcpp-projects) [Ablauf](https://www.dcpp-digital.de/#dcpp-process) [Kontakt](https://www.dcpp-digital.de/#dcpp-contact)\n\nPROJEKT · APP-ENTWICKLUNG · IN ENTWICKLUNG\n\n# Kochheld.\n\nKoch-App für vorhandene Lebensmittel: Zutaten eintragen, Wünsche wählen und daraus passende Gerichte mit Einkaufshilfe und Favoriten entwickeln.\n\n[App ansehen](https://www.dcpp-digital.de/#Kochheld) [App anfragen](https://www.dcpp-digital.de/#dcpp-contact)\n\nKochheld – App-Projekt von DCPP Digital\n\nKoch-App Vorrat nutzen Rezepte & Einkauf In Entwicklung\n\nAUSGANGSLAGE\n\n## Im Vorrat steckt oft mehr als gedacht.\n\nEinzelne Lebensmittel bleiben übrig, während für das nächste Gericht trotzdem neu eingekauft wird. Die eigentliche Frage ist oft schlicht: Was kann ich aus dem machen, was\nschon da ist?\n\nZIEL\n\n## Aus vorhandenen Zutaten schneller zum Essen.\n\nKochheld soll wenige vorhandene Zutaten mit persönlichen Wünschen verbinden und daraus passende, verständliche Kochideen ableiten – ohne zuerst den kompletten Haushalt\nerfassen zu müssen.\n\nUMSETZUNG\n\n## Vom Vorrat zur Kochidee.\n\nZutaten Vorhandene Lebensmittel werden schnell erfasst und können priorisiert werden.\n\nWünsche & Filter Tageszeit, warm oder kalt sowie geplante Ernährungsfilter helfen bei der Auswahl.\n\nRezepte Passende Gerichte zeigen Zutaten, Zubereitung und fehlende Bestandteile verständlich an.\n\nEinkauf & Favoriten Fehlendes kann in die Einkaufsliste wandern, gute Ideen lassen sich für später merken.\n\nERGEBNIS\n\n## Ein klar umrissenes Produkt in Entwicklung.\n\nKochheld verbindet Resteverwertung mit einfacher Rezeptfindung und einer freundlichen Markenwelt. Die App befindet sich in Entwicklung; zentrale Nutzerwege und\nBeispielinhalte sind bereits ausgearbeitet.\n\n[Testversion anfragen](mailto:kontakt@dcpp-digital.de?subject=Kochheld%20%E2%80%93%20Interesse%20an%20der%20Testversion)\n[App anfragen](https://www.dcpp-digital.de/#dcpp-contact)\n\nDCPP DIGITAL · APP-ENTWICKLUNG\n\n## Eine alltagstaugliche App-Idee geplant?\n\nDCPP übersetzt den Kernnutzen in einfache Nutzerwege, klare Oberflächen und einen realistischen Entwicklungsumfang.\n\n[E-Mail](mailto:kontakt@dcpp-digital.de?subject=Kochheld%20Anfrage) [Anrufen](tel:+4920419862645) [WhatsApp](https://wa.me/message/M3USW7QBLDWYM1)\n\n[DCPP Digital Develop • Content • Create](https://www.dcpp-digital.de/#dcpp-start)\n\n[Projekte](https://www.dcpp-digital.de/#dcpp-projects) [Kontakt](https://www.dcpp-digital.de/#dcpp-contact) [Impressum](https://www.dcpp-digital.de/about/#dcpp-impressum-page) [Datenschutz](https://www.dcpp-digital.de/j/privacy)\n\n© 2026 DCPP Digital · Develop • Content • Create\n"},"?projekt=digital-publishing":{"canonical":"https://www.dcpp-digital.de/?projekt=digital-publishing","markdown":"# DCPP Digital Publishing – DCPP Digital\n\nDCPP Digital Publishing bündelt veröffentlichte Bücher und digitale PDF-Produkte – mit Projektbildern, Beschreibungen und direkten Anbieterlinks.\n\nKanonische Projektadresse: https://www.dcpp-digital.de/?projekt=digital-publishing\n\n[← ZURÜCK ZU DCPP DIGITAL](https://www.dcpp-digital.de/#dcpp-start)DCPP DIGITAL · PUBLISHING\n\n[DCPP Digital D-Arrow Signet DCPP DIGITALDIGITAL PUBLISHING](https://www.dcpp-digital.de/#dcpp-start)\n\n[Bücher](https://www.dcpp-digital.de/#digitalpublishing-print)[PDF-Downloads](https://www.dcpp-digital.de/#digitalpublishing-produkte)[So funktioniert's](https://www.dcpp-digital.de/#digitalpublishing-ablauf)[Kontakt](https://www.dcpp-digital.de/#digitalpublishing-kontakt)\n\nDCPP DIGITAL PUBLISHING\n\n# Bücher & digitale Produkte. Eigenständig entwickelt.\n\nVon veröffentlichten Buchprojekten bis zu direkt nutzbaren PDF-Produkten – konzipiert, gestaltet und publikationsfertig umgesetzt.\n\n[Produkte entdecken](https://www.dcpp-digital.de/#digitalpublishing-print)[So funktioniert's](https://www.dcpp-digital.de/#digitalpublishing-ablauf)\n\nPRINT BücherPDF DownloadsDCPP Eigenständig entwickelt\n\nDCPP\n\nDIGITALPUBLISHINGDevelop · Content · Create\n\nPRINT PUBLISHING\n\n## Bücher & Kreativprojekte.\n\nDen Auftakt bilden die veröffentlichten Buch- und Kreativprojekte von DCPP Digital – mit sichtbarem Produkt, verständlicher Beschreibung und direktem Weg zum jeweiligen\nAngebot.\n\nKREATIVBUCH · PRINT\n\n### Doggen & Blumen\n\nDas große Ausmalbuch.\n\n[Doggen & Blumen – Das große Ausmalbuch](https://www.amazon.de/dp/B0HLXCQJ87?ref=cm_sw_r_ffobk_cso_cp_mwn_dp_VPNF0ZMXPGQ2ZNV62QYY&ref_=cm_sw_r_ffobk_cso_cp_mwn_dp_VPNF0ZMXPGQ2ZNV62QYY&social_share=cm_sw_r_ffobk_cso_cp_mwn_dp_VPNF0ZMXPGQ2ZNV62QYY&bestFormat=true&dplnkId=2bd0aceb-7b70-4db8-806a-7143653740e8&nodl=1)\n\nAusmalbuch mit 50 liebevoll gestalteten Motiven rund um Deutsche Doggen und Blumen – als eigenständiges DCPP-Publishing-Projekt für kreative Auszeiten, Doggenfans und\nNaturfreunde.\n\n50 MotiveDeutsche DoggenBlumenAusmalbuch\n\n[Bei Amazon ansehen →](https://www.amazon.de/dp/B0HLXCQJ87?ref=cm_sw_r_ffobk_cso_cp_mwn_dp_VPNF0ZMXPGQ2ZNV62QYY&ref_=cm_sw_r_ffobk_cso_cp_mwn_dp_VPNF0ZMXPGQ2ZNV62QYY&social_share=cm_sw_r_ffobk_cso_cp_mwn_dp_VPNF0ZMXPGQ2ZNV62QYY&bestFormat=true&dplnkId=2bd0aceb-7b70-4db8-806a-7143653740e8&nodl=1)\n\nKREATIVBUCH · PRINT\n\n### Malen mit Textmarker\n\nFarbe trifft Struktur.\n\n[Malen mit Textmarker](https://www.amazon.de/dp/B0HN75GGM1)\n\n50 kreative Ausmalbilder für Alltag, Büro, Haushalt, Garten & Wohlfühlmomente – für Jugendliche & Erwachsene und für das Ausmalen mit sechs\nTextmarker-Grundfarben entwickelt.\n\n50 Motive6 FarbenTextmarkerAusmalbuch\n\n[Bei Amazon ansehen →](https://www.amazon.de/dp/B0HN75GGM1)\n\nKOCHBUCH · PRINT\n\n### 69× SATT. STARK. LEICHT.\n\nAbnehmen. Fitness. Bewusste Ernährung.\n\n[69× SATT. STARK. LEICHT. – Kochbuch für Abnehmen, Fitness und bewusste Ernährung](https://www.amazon.de/dp/B0HM3NWZV3?spcref=PRINT_LISTING)\n\n69 bebilderte Rezepte für Frühstück, Mittag- und Abendessen – alltagstauglich, verständlich erklärt und Schritt für Schritt nachzukochen. Mit Kalorien, Protein und\nBallaststoffen pro Portion sowie vegetarischen und gekennzeichneten Keto-Optionen.\n\n69 RezepteBebildertFitnessBewusste Ernährung\n\n[Bei Amazon ansehen →](https://www.amazon.de/dp/B0HM3NWZV3?spcref=PRINT_LISTING)\n\nKOCHBUCH · PRINT\n\n### Overnight Oats\n\nFrühstück & Abend einfach vorbereitet.\n\n[Overnight Oats – Rezeptbuch für einfache Frühstücks- und Abendideen](https://www.amazon.de/dp/B0HM6RVL5L?spcref=PRINT_LISTING)\n\nRezeptbuch rund um Overnight Oats mit modernen, alltagstauglichen Ideen für Frühstück und Abend. Einfach vorbereitet, leicht nachzumachen und ideal für eine bewusste,\npraktische Ernährung mit Genuss.\n\nOvernight OatsFrühstückAbendRezeptbuch\n\n[Bei Amazon ansehen →](https://www.amazon.de/dp/B0HM6RVL5L?spcref=PRINT_LISTING)\n\nKINDER-AUSMALBUCH · PRINT\n\n### Malen mit Textmarker – Kinder Edition\n\nLesen. Finden. Ausmalen.\n\n[Malen mit Textmarker – Kinder Edition: Kinder-Ausmalbuch im Querformat mit Vorder- und Rückseite](https://www.amazon.de/dp/B0HP5RXXLZ/ref=sr_1_1?__mk_de_DE=%C3%85M%C3%85%C5%BD%C3%95%C3%91&crid=7JPBXEQI2N7I&dib=eyJ2IjoiMSJ9.PTESFTtItNkIE22DLXxN6uYvy-3xO8ZnVPn2Xc3WShCam2-uelNpvMDDx3f1YlKq6TH6yoX1Zqlq6NveJpQ_5VYecc-y0uHhgOh0Qq03y0an5YPMJjIOAmgFKzTocjQxY2tE1TwcBZmPpnuL3co8OVy7NouLwUCw7ppp2CFQQkCrKHDrx9eM5WpW0lxphDWKZc83iKtj6peDLucKS5lAS3zcred8s-aJYlPSSKfqEHk.6TaUiDgNvDxOsPl8d9okRXQLZoRgTS4mSAsut1yl39U&dib_tag=se&keywords=Malen+mit+Textmarker+%E2%80%93+Kinder+Edition%3A+Ausmalen+mit+Farbennamen&qid=1792833901&sprefix=malen+mit+textmarker+kinder+edition+ausmalen+mit+farbennamen+%2Caps%2C144&sr=8-1)\n\n50 fantasievolle Ausmalmotive für Kinder von 6 bis 12 Jahren. Mit sechs Farbnamen zum Lesen, Entdecken und Ausmalen – von Tieren und Natur bis zu bunten Fantasiewelten.\n\nKinder-Ausmalbuch50 Motive6–12 JahreTextmarker\n\n[Bei Amazon ansehen →](https://www.amazon.de/dp/B0HP5RXXLZ/ref=sr_1_1?__mk_de_DE=%C3%85M%C3%85%C5%BD%C3%95%C3%91&crid=7JPBXEQI2N7I&dib=eyJ2IjoiMSJ9.PTESFTtItNkIE22DLXxN6uYvy-3xO8ZnVPn2Xc3WShCam2-uelNpvMDDx3f1YlKq6TH6yoX1Zqlq6NveJpQ_5VYecc-y0uHhgOh0Qq03y0an5YPMJjIOAmgFKzTocjQxY2tE1TwcBZmPpnuL3co8OVy7NouLwUCw7ppp2CFQQkCrKHDrx9eM5WpW0lxphDWKZc83iKtj6peDLucKS5lAS3zcred8s-aJYlPSSKfqEHk.6TaUiDgNvDxOsPl8d9okRXQLZoRgTS4mSAsut1yl39U&dib_tag=se&keywords=Malen+mit+Textmarker+%E2%80%93+Kinder+Edition%3A+Ausmalen+mit+Farbennamen&qid=1792833901&sprefix=malen+mit+textmarker+kinder+edition+ausmalen+mit+farbennamen+%2Caps%2C144&sr=8-1)\n\nKINDERBUCH · PRINT\n\n### Spinnetou sucht das Glück\n\nFreundschaft. Familie. Glück.\n\nSpinnetou sucht das Glück – Kinderbuch\n\nEine liebevoll erzählte Geschichte für Kinder der Klassen 1 bis 4. Spinnetou sucht nach Freundschaft, Familie und Glück – mit einfachen Texten und einer positiven Botschaft.\n\nKinderbuchKlasse 1–4FreundschaftFamilie\n\nAmazon · Link folgt\n\nDIGITALE PRODUKTE\n\n## Entwickelt für die Nutzung. Nicht für den schnellen Effekt.\n\nJedes Produkt verfolgt einen klaren Zweck. Inhalt, Aufbau und Gestaltung werden darauf ausgerichtet, Informationen verständlich zu vermitteln und im Alltag tatsächlich nutzbar\nzu machen.\n\nDCPP DIGITALFOCUS\n\n& BRAINKonzentration · Logik · Alltagsfokus30 ARBEITSBLÄTTER\n\nDIGITALER DOWNLOADPDF · A4\n\n### Focus & Brain\n\nKonzentration, Logik & Alltagsfokus\n\n30 Arbeitsblätter für Konzentration, Logik und Alltagsfokus – strukturiert, druckfertig und inklusive Lösungen.\n\n30 Arbeitsblätterinkl. LösungenDeutsch\n\nPreis6,90 €\n\n[Details →](https://payhip.com/b/wUe2g)[Kaufen →](https://payhip.com/buy?link=wUe2g)\n\nDCPP DIGITALOMA,\n\nERZÄHL MIR\n\nVON FRÜHERErinnerungen, die bleiben.72 ERINNERUNGSSEITEN\n\nDIGITALER DOWNLOADPDF · A4\n\n### Oma, erzähl mir von früher\n\nErinnerungen, die bleiben.\n\n72 geführte Erinnerungsseiten für Geschichten, Familienmomente, Rezepte und Fotos – in zwei PDF-Versionen.\n\n72 Erinnerungsseiten2 PDF-VersionenDeutsch\n\nPreis9,90 €\n\n[Details →](https://payhip.com/b/FZahj)[Kaufen →](https://payhip.com/buy?link=FZahj)\n\nDCPP DIGITALALLTAG\n\nIM GRIFFPlanen · Organisieren · Überblick behalten50 VORLAGEN\n\nDIGITALER DOWNLOADPDF · A4\n\n### Alltag im Griff\n\n50 Planer & Checklisten\n\n50 Planer und Checklisten für Haushalt, Woche, Einkauf, Budget und Familie – für mehr Übersicht im Alltag.\n\n50 VorlagenOrganisationDeutsch\n\nPreis7,90 €\n\n[Details →](https://payhip.com/b/S5uGh)[Kaufen →](https://payhip.com/buy?link=S5uGh)\n\nDCPP DIGITALMEIN\n\nWELPEN\n\nPLANERWachstum · Training · Alltag · ErinnerungenDAS ERSTE JAHR\n\nDIGITALER DOWNLOADPDF · A4\n\n### Mein Welpenplaner\n\nPlaner & Tagebuch für die Welpenzeit\n\nPlaner und Tagebuch für Entwicklung, Gewicht, Fütterung, Training, Termine, Spaziergänge, Ausgaben und Erinnerungen.\n\nWelpenzeitPlaner & TagebuchDeutsch\n\nPreis8,90 €\n\n[Details →](https://payhip.com/b/QPS3O)[Kaufen →](https://payhip.com/buy?link=QPS3O)\n\nDie Zahlungsabwicklung und Bereitstellung der digitalen Produkte erfolgen über Payhip. Es erfolgt kein physischer Versand.\n\nUmsatzsteuer-Hinweis: DCPP Digital wendet die Kleinunternehmerregelung gemäß § 19 UStG an und weist selbst keine Umsatzsteuer aus. Bei digitalen Produkten kann\nPayhip – abhängig vom Käuferland und den geltenden steuerlichen Vorgaben – im Checkout Steuern bzw. VAT berechnen und abführen.\n\nDIGITAL. DIREKT. VERSTÄNDLICH.\n\n## Vom Produkt zum passenden Anbieter.\n\nBücher führen direkt zum jeweiligen Amazon-Angebot, digitale PDF-Produkte zu Payhip. Vor dem Wechsel ist klar ersichtlich, worum es geht und in welchem Format das Produkt\nangeboten wird.\n\n### Produkt auswählen\n\nBuch oder PDF auswählen und Inhalt, Umfang sowie Produktart direkt auf der DCPP-Seite einordnen.\n\n### Anbieter öffnen\n\nDer jeweilige Button führt bei Büchern zu Amazon und bei digitalen Produkten zu Payhip.\n\n### Kauf abschließen\n\nBestellung, Zahlung, Bereitstellung oder Versand erfolgen anschließend über den jeweils ausgewiesenen Anbieter.\n\nDCPP DIGITAL\n\n## Fragen zu einem Produkt?\n\nBei Fragen zu Inhalt, Dateiformat oder Nutzung eines Produkts ist DCPP Digital direkt erreichbar.\n\n[E-Mail](mailto:kontakt@dcpp-digital.de?subject=Anfrage%20Digital%20Publishing) [Anrufen](tel:+4920419862645) [WhatsApp](https://wa.me/message/M3USW7QBLDWYM1)\n\n[DCPP Digital Develop • Content • Create](https://www.dcpp-digital.de/#dcpp-start) Digitale Produkte · Publishing · DCPP Digital\n\n[Impressum](https://www.dcpp-digital.de/about/#dcpp-impressum-page)•[Datenschutz](https://www.dcpp-digital.de/j/privacy)•[DCPP Digital](https://www.dcpp-digital.de/#dcpp-start)\n\n© 2026 DCPP Digital · Develop • Content • Create\n"},"?projekt=olympia-bottrop":{"canonical":"https://www.dcpp-digital.de/?projekt=olympia-bottrop","markdown":"# Restaurant Olympia – DCPP Digital\n\nMediterranes DCPP-Webkonzept für Restaurant Olympia in Bottrop-Grafenwald mit Speisekarte, Kegelbahn, Besuchsplanung und direktem Kontakt.\n\nKanonische Projektadresse: https://www.dcpp-digital.de/?projekt=olympia-bottrop\n\n[DCPP Digital](https://www.dcpp-digital.de/#dcpp-start)[Alle Projekte](https://www.dcpp-digital.de/#dcpp-projects)\n\n[Leistungen](https://www.dcpp-digital.de/#dcpp-services)[Projekte](https://www.dcpp-digital.de/#dcpp-projects)[Kontakt](https://www.dcpp-digital.de/#dcpp-contact)\n\nPROJEKT · GASTRONOMIE · DESIGNKONZEPT\n\n# Restaurant Olympia.\n\nGriechisch. Gesellig. Grafenwald. Ein eigener Auftritt für Restaurant und Kegelbahn – mit Originalfotos, markanter Typografie und direktem Kontakt.\n\n[Microsite ansehen](https://www.dcpp-digital.de/#olympiabottrop)[Webprojekt anfragen](https://www.dcpp-digital.de/#dcpp-contact)\n\nRestaurant Olympia – Original-Geschäftslogo\n\nGastro-MicrositeMobile NutzerführungSEO/GEO vorbereitetKonzeptstudie\n\nDAS ZIEL\n\n## Eine eigene Website für Olympia.\n\nDas inhabergeführte Restaurant von Loukas Kaiafas und Dimitris Kaiafas erhält einen eigenen digitalen Auftritt. Gäste finden auf einen Blick den Standort in\nBottrop-Grafenwald, die Speisekarte und die Öffnungszeiten. Klare Wege führen zur Tischanfrage, zur Kegelbahn und zur Anfahrt.\n\nDIE GESTALTUNG\n\n## Eine Handschrift für Olympia.\n\nMarkante Schrift, warme Farben aus dem Olympia-Logo und großzügig gesetzte Restaurantfotos schaffen einen unverwechselbaren Auftritt. Dezente griechische Worte mit\ndeutscher Übersetzung setzen persönliche Akzente. Im Mittelpunkt stehen griechische Küche, gemeinsame Abende und die Kegelbahn in Grafenwald.\n\nDIE NUTZERFÜHRUNG\n\n## Die Karte im Blick. Den Besuch im Plan.\n\nSpeisekarte, Abholung und Besuchsplanung erhalten eigene Wege. Eine lokale Anfragehilfe bereitet Wunschtag und Personenzahl vor; gebucht wird persönlich am Telefon.\nGastgeber, Küche und Kegelbahn geben dem Auftritt seine eigenständige Dramaturgie.\n\nPROJEKTSTATUS\n\n## Konzipiert und implementiert.\n\nVon DCPP Digital als eigenständiges Restaurantkonzept entwickelt und als interaktive Vorschau umgesetzt. Originalfotos, Olympia-Logo, Speisekartenauszug, Inhabernamen und\ndie aktualisierten Öffnungszeiten sind integriert. Die Vorschau zeigt die gestalterische und funktionale Grundlage für eine künftige eigene Restaurantwebsite.\n\n[Olympia-Microsite entdecken](https://www.dcpp-digital.de/#olympiabottrop)[Zur Projektübersicht](https://www.dcpp-digital.de/#dcpp-projects)\n\nDCPP DIGITAL · WEBDESIGN\n\n## Auch eine Website geplant?\n\nDCPP Digital erstellt individuelle Webseiten für Unternehmen und lokale Betriebe – passend zu Angebot, Zielgruppe und Arbeitsabläufen.\n\n[E-Mail](mailto:kontakt@dcpp-digital.de?subject=Webdesign-Anfrage) [Anrufen](tel:+4920419862645) [WhatsApp](https://wa.me/message/M3USW7QBLDWYM1)\n\n[DCPP Digital Develop • Content • Create](https://www.dcpp-digital.de/#dcpp-start)\n\n[Projekte](https://www.dcpp-digital.de/#dcpp-projects) [Kontakt](https://www.dcpp-digital.de/#dcpp-contact) [Impressum](https://www.dcpp-digital.de/about/#dcpp-impressum-page) [Datenschutz](https://www.dcpp-digital.de/j/privacy)\n\nEin Webkonzept von DCPP Digital.  ·  © 2026 DCPP Digital · Develop · Content · Create\n"},"/about/":{"canonical":"https://www.dcpp-digital.de/about/","markdown":"[DCPP Digital – Develop Content Create](https://www.dcpp-digital.de/)\n\nIMPRESSUM\n\n# Impressum\n\n## Angaben gemäß § 5 DDG\n\nPatrick Pretzer\n\nDCPP Digital – Develop • Content • Create\n\nKirchhellenerstraße 262\n\n46240 Bottrop\n\nDeutschland\n\nE-Mail: [kontakt@dcpp-digital.de](mailto:kontakt@dcpp-digital.de)\n\nTelefon: [+49 2041 9862645](tel:+4920419862645)\n\n## Umsatzsteuer\n\nDCPP Digital wendet die Kleinunternehmerregelung gemäß § 19 UStG an. Daher wird keine Umsatzsteuer ausgewiesen.\n\n## Verantwortlich für den Inhalt\n\nPatrick Pretzer\n\nKirchhellenerstraße 262\n\n46240 Bottrop\n\n[Zur Startseite](https://www.dcpp-digital.de/) [Datenschutz](https://www.dcpp-digital.de/j/privacy)\n"},"/j/privacy":{"canonical":"https://www.dcpp-digital.de/j/privacy","markdown":"DATENSCHUTZ\n\n# Datenschutzerklärung\n\nStand: 22. Oktober 2026\n\n## 1. Verantwortlicher\n\nPatrick Pretzer\n\nDCPP Digital – Develop • Content • Create\n\nKirchhellenerstraße 262\n\n46240 Bottrop\n\nDeutschland\n\nE-Mail: [kontakt@dcpp-digital.de](mailto:kontakt@dcpp-digital.de)\n\nTelefon: [+49 2041 9862645](tel:+4920419862645)\n\n## 2. Allgemeine Hinweise zur Datenverarbeitung\n\nPersonenbezogene Daten werden auf dieser Webseite nur verarbeitet, soweit dies für die technische Bereitstellung, Sicherheit, Kommunikation oder die Nutzung der angebotenen\nFunktionen erforderlich ist. Rechtsgrundlagen können insbesondere Art. 6 Abs. 1 lit. b, lit. f oder – bei einer Einwilligung – lit. a DSGVO sein.\n\nDie Übertragung dieser Webseite erfolgt verschlüsselt über HTTPS.\n\n## 3. Hosting und technische Bereitstellung\n\nFür die technische Bereitstellung dieser Webseite werden beim Aufruf technisch erforderliche Verbindungs- und Server-Log-Daten verarbeitet. Dazu können insbesondere die\nIP-Adresse, Datum und Uhrzeit des Zugriffs, die aufgerufene Seite, Browser- und Geräteinformationen sowie gegebenenfalls die zuvor besuchte Seite gehören.\n\nDie Verarbeitung erfolgt zur stabilen, sicheren und funktionsfähigen Bereitstellung der Webseite, zur Fehleranalyse sowie zur Erkennung und Abwehr von Missbrauch. Rechtsgrundlage\nist das berechtigte Interesse an einem sicheren technischen Betrieb gemäß Art. 6 Abs. 1 lit. f DSGVO.\n\n## 4. Cookies und Einwilligungsverwaltung\n\nDiese Webseite verwendet eine Einwilligungsverwaltung für Cookies und vergleichbare Speicherzugriffe. Technisch unbedingt erforderliche Cookies oder vergleichbare Zugriffe können\neingesetzt werden, soweit sie für die Bereitstellung eines ausdrücklich gewünschten digitalen Dienstes notwendig sind. Optionale Kategorien dürfen erst nach einer entsprechenden\nEinwilligung geladen werden.\n\nRechtsgrundlage für technisch erforderliche Zugriffe ist § 25 Abs. 2 TDDDG in Verbindung mit Art. 6 Abs. 1 lit. f DSGVO. Soweit eine Einwilligung erforderlich ist, erfolgt die\nVerarbeitung auf Grundlage von § 25 Abs. 1 TDDDG und Art. 6 Abs. 1 lit. a DSGVO. Eine erteilte Einwilligung kann über die auf der Webseite bereitgestellten Cookie-Einstellungen\nfür die Zukunft geändert oder widerrufen werden.\n\n## 5. Google Analytics\n\nDiese Webseite nutzt Google Analytics 4, einen Webanalysedienst der Google Ireland Limited, Gordon House, Barrow Street, Dublin 4, Irland. Die Einbindung erfolgt über die in Jimdo\nCreator vorgesehene Google-Analytics-Funktion und ist dem Cookie-Bereich „Performance“ zugeordnet.\n\nGoogle Analytics wird erst aktiviert, wenn Sie über den Cookie-Banner ausdrücklich in die Verwendung von Performance-Cookies eingewilligt haben. Dabei können insbesondere\nInformationen über Seitenaufrufe, Scrollvorgänge, Klicks auf externe Links, Website-Suchen, Dateidownloads und weitere Nutzungsereignisse verarbeitet werden. Die Verarbeitung\nerfolgt auf Grundlage Ihrer Einwilligung gemäß Art. 6 Abs. 1 lit. a DSGVO in Verbindung mit § 25 Abs. 1 TDDDG.\n\nEine erteilte Einwilligung können Sie jederzeit mit Wirkung für die Zukunft über die Cookie-Einstellungen dieser Webseite ändern oder widerrufen. Ohne Einwilligung in die\nKategorie „Performance“ wird Google Analytics über den Jimdo-Cookie-Mechanismus nicht aktiviert.\n\nIm Rahmen der Nutzung von Google Analytics kann eine Verarbeitung von Daten durch Google-Unternehmen oder Dienstleister außerhalb der Europäischen Union bzw. des Europäischen\nWirtschaftsraums nicht ausgeschlossen werden. Weitere Informationen zur Datenverarbeitung durch Google finden Sie unter [policies.google.com/privacy](https://policies.google.com/privacy).\n\n## 6. Schriftarten über Bunny Fonts\n\nFür die einheitliche Darstellung von Schriftarten nutzt diese Webseite Bunny Fonts von BunnyWay d.o.o. Die benötigten Schriftdateien werden über fonts.bunny.net geladen.\nBunny Fonts erklärt, keine personenbezogenen Daten oder Nutzungslogs der Webseitenbesucher zu speichern und keine Tracking-Cookies für diesen Dienst einzusetzen.\n\n## 7. Kontaktaufnahme per E-Mail, Telefon oder WhatsApp\n\nWenn Sie DCPP Digital per E-Mail oder Telefon kontaktieren, werden die von Ihnen mitgeteilten Daten verarbeitet, um Ihre Anfrage zu beantworten. Soweit die Anfrage auf die\nAnbahnung oder Durchführung eines Vertrags gerichtet ist, erfolgt die Verarbeitung auf Grundlage von Art. 6 Abs. 1 lit. b DSGVO. In anderen Fällen erfolgt sie auf Grundlage des\nberechtigten Interesses an der Bearbeitung von Anfragen gemäß Art. 6 Abs. 1 lit. f DSGVO.\n\nAnfragedaten werden gelöscht, sobald sie für die Bearbeitung nicht mehr erforderlich sind und keine gesetzlichen Aufbewahrungspflichten oder berechtigten Gründe für eine weitere\nSpeicherung entgegenstehen.\n\nZusätzlich bieten wir einen freiwilligen Kontakt über WhatsApp Business an. Der WhatsApp-Button ist ein externer Link und lädt beim bloßen Besuch dieser Webseite kein\nWhatsApp-Chat-Widget. Erst beim Anklicken wird WhatsApp geöffnet. Wenn Sie uns dort schreiben, verarbeiten wir Ihre Telefonnummer, Ihren angezeigten Namen und die übermittelten\nNachrichten zur Bearbeitung Ihrer Anfrage. Für die Verarbeitung der Anfrage gelten je nach Anlass Art. 6 Abs. 1 lit. b bzw. lit. f DSGVO. Daneben verarbeitet WhatsApp Ireland\nLimited als Anbieter der Kommunikationsplattform Daten nach eigenen Datenschutzbedingungen; eine Verarbeitung außerhalb des Europäischen Wirtschaftsraums kann nicht ausgeschlossen\nwerden. Alternativ können Sie uns jederzeit per E-Mail oder Telefon kontaktieren.\n\n## 8. DCPP Digital Publishing und Payhip\n\nDigitale PDF-Produkte werden über externe Links zu Payhip angeboten. Erst wenn Sie einen entsprechenden Link oder Kaufbutton anklicken, verlassen Sie die DCPP-Webseite und\nwechseln zum Angebot von Payhip. Dort können für die Kaufabwicklung insbesondere Kontakt-, Bestell-, Zahlungs- und steuerlich erforderliche Daten verarbeitet werden. Für die\ndortige Verarbeitung gelten die Datenschutz- und Vertragsbedingungen von Payhip sowie gegebenenfalls der eingesetzten Zahlungsdienstleister.\n\n## 9. Externe Links und Plattformen\n\nDiese Webseite enthält externe Links, unter anderem zu Amazon, Payhip, Instagram, Facebook, LinkedIn, WhatsApp, TikTok, GitHub, Google Maps sowie zu externen Projektseiten. Diese\nAngebote sind auf der DCPP-Webseite grundsätzlich als Links eingebunden und werden nicht allein durch das Vorhandensein des Links als Inhalt der jeweiligen Plattform geladen. Erst\nbeim Anklicken eines externen Links wird eine Verbindung zum jeweiligen Anbieter hergestellt.\n\nAb diesem Zeitpunkt gelten die Datenschutzbestimmungen des jeweiligen externen Anbieters. Je nach Anbieter kann eine Verarbeitung personenbezogener Daten auch außerhalb der\nEuropäischen Union bzw. des Europäischen Wirtschaftsraums stattfinden.\n\n## 10. Speicherdauer\n\nPersonenbezogene Daten werden grundsätzlich nur so lange gespeichert, wie dies für den jeweiligen Zweck erforderlich ist. Technische Protokolldaten werden nur für den Zeitraum\nvorgehalten, der für Betrieb, Sicherheit und Fehleranalyse erforderlich ist. Gesetzliche Aufbewahrungs- und Nachweispflichten bleiben unberührt.\n\n## 11. Ihre Rechte\n\nSie haben im Rahmen der gesetzlichen Voraussetzungen insbesondere das Recht auf Auskunft, Berichtigung, Löschung, Einschränkung der Verarbeitung, Datenübertragbarkeit und\nWiderspruch. Soweit eine Verarbeitung auf Ihrer Einwilligung beruht, können Sie diese Einwilligung jederzeit mit Wirkung für die Zukunft widerrufen.\n\nAußerdem haben Sie das Recht, sich bei einer Datenschutz-Aufsichtsbehörde zu beschweren.\n\n## 12. Zuständige Datenschutz-Aufsichtsbehörde\n\nLandesbeauftragte für Datenschutz und Informationsfreiheit Nordrhein-Westfalen (LDI NRW)\n\nKavalleriestraße 2–4\n\n40213 Düsseldorf\n\nE-Mail: [poststelle@ldi.nrw.de](mailto:poststelle@ldi.nrw.de)\n\n## 13. Aktualisierung dieser Datenschutzerklärung\n\nDiese Datenschutzerklärung wird angepasst, wenn sich Funktionen, eingesetzte Dienste oder rechtliche Anforderungen der Webseite ändern.\n\n[Zur Startseite](https://www.dcpp-digital.de/) [Impressum](https://www.dcpp-digital.de/about/#dcpp-impressum-page)\n"},"/olympia-bottrop":{"canonical":"https://www.dcpp-digital.de/olympia-bottrop","markdown":"[Zum Inhalt](https://www.dcpp-digital.de/#oly-main)\n\n[DCPP DIGITAL](https://www.dcpp-digital.de/#dcpp-projects) DESIGNKONZEPT · Kein offizieller Restaurantauftritt\n\n[Restaurant Olympia – Original-Geschäftslogo Griechisches Restaurant in Bottrop-Grafenwald](https://www.dcpp-digital.de/#oly-start)\n\n[Speisekarte](https://www.dcpp-digital.de/#oly-speisekarte)[Einblicke](https://www.dcpp-digital.de/#oly-einblicke)[Kegelbahn](https://www.dcpp-digital.de/#oly-kegelbahn)[Bewertungen](https://www.dcpp-digital.de/#oly-bewertungen)[Besuch & Zeiten](https://www.dcpp-digital.de/#oly-besuch)\n\n[Tisch anfragen](tel:+4920455136)\n\nΚαλώς ήρθατεWillkommen im Olympia\n\nGriechisches Restaurant mit Kegelbahn · Bottrop-Grafenwald\n\n# Griechisch. Gesellig. Grafenwald.\n\nIm Olympia treffen griechische Küche und gemeinsame Abende aufeinander. Genießen Sie Ihren Besuch in Grafenwald – oder bestellen Sie alle Speisen und Getränke zur Abholung\nvor.\n\n[Tisch anfragen](tel:+4920455136)[Zur Speisekarte](https://www.dcpp-digital.de/#oly-speisekarte)[Zur Abholung vorbestellen](https://www.dcpp-digital.de/#oly-abholung)\n\nHegestraße 15 · 46244 Bottrop\n\nGrillspezialitäten mit Gyros, Pommes, roten Zwiebeln und Tzatziki im Restaurant Olympia\n\nGriechisch genießen. In Grafenwald zuhause.\n\nGedeckte Tische im Gastraum des Olympia in Grafenwald\n\nEin Platz für Ihre Runde.\n\n[02045 5136Tisch & Kegelbahn anfragen](tel:+4920455136) [Do–So ab 17 UhrSonntag auch 11:30–14:30 Uhr · Alle Zeiten](https://www.dcpp-digital.de/#oly-oeffnungszeiten) [Hegestraße 15 · GrafenwaldRoute mit Google Maps planen](https://www.google.com/maps/dir/?api=1&destination=Restaurant+Olympia,+Hegestra%C3%9Fe+15,+46244+Bottrop)\n\nDas Olympia genießen\n\n## Ihre Gastgeber.\n\nLoukas Kaiafas\n\n& Dimitris Kaiafas\n\nInhabergeführt in Bottrop-Grafenwald. Griechische Küche, ein Tisch für Ihre Runde und eine eigene Kegelbahn – das ist Olympia.\n\n[Ihren Besuch planen](https://www.dcpp-digital.de/#oly-anfrage)\n\nPorträt eines Olympia-Inhabers im Außenbereich\n\nPorträt eines Olympia-Inhabers an der Restauranttheke\n\nΚαλή όρεξηGuten Appetit\n\n## Die Küche im Olympia.\n\nGyros, Grillspezialitäten und Gerichte aus dem Ofen. Sehen Sie sich die Kartenseite an oder öffnen Sie gezielt eine Kategorie. Die vollständige Speisen- und Getränkekarte\nergänzen wir hier.\n\nSpeisekarte Seite 1: Gyros-Spezialitäten und Spezialgerichte mit Preisen\n\nSpeisekarte · Gyros-Spezialitäten & Spezialgerichte\n\nZurück\n\nSeite 1 von 1\n\nWeiter\n\nSpeisekartenauszug · Seite für Seite ansehen. [Kartenseite groß öffnen](https://u.jimcdn.com/cms/o/s7cb3eb94c4ad4045/userlayout/img/04-olympia-speisekarte-seite-01.jpg?t=1792397882)\n\nAlle\nGerichteGyros-SpezialitätenSpezialgerichte\n\nKategorie wählen, um die Gerichte anzuzeigen.\n\nAlle Gerichte als Text anzeigen +\n\nNR. 62\n\n### Gyros\n\nMit Tzatziki.\n\n14,50 €\n\nNR. 63\n\n### Gyros-Metaxa\n\nMit Metaxasauce und Käse überbacken.\n\n15,00 €\n\nNR. 64\n\n### Gyros-Pfanne\n\nMit Pfeffersauce, Zwiebeln und Käse überbacken.\n\n15,00 €\n\nNR. 65\n\n### Gyros-Pfanne Hollandaise\n\nMit Zwiebeln, Sauce Hollandaise und Käse überbacken.\n\n15,00 €\n\nNR. 66\n\n### Samos-Teller\n\nGyros, Calamaris und Tzatziki.\n\n16,00 €\n\nNR. 67\n\n### Seniorenteller\n\nSchweinefiletspieß mit Sauce Hollandaise.\n\n14,50 €\n\nNR. 69\n\n### Eva-Teller\n\nSouvlaki, Steak, Putenfilet und Tzatziki.\n\n15,50 €\n\nNR. 71\n\n### Bifteki\n\nGefüllt mit Tomaten und Schafskäse, mit Metaxasauce und Gouda überbacken.\n\n17,50 €\n\nNR. 73\n\n### Schweinefiletmedaillons\n\nMit Metaxasauce und Gouda überbacken.\n\n17,50 €\n\nNR. 74\n\n### Schweinefiletmedaillons mit Ananas\n\nMit Ananas, Sauce nach Wahl und Gouda überbacken.\n\n18,50 €\n\nNR. 75\n\n### Schweinemedaillons\n\nMit Sauce nach Wahl.\n\n18,50 €\n\nNR. 78\n\n### Syrtaki-Teller\n\nGanzes Schweinefilet mit Sauce nach Wahl.\n\n19,50 €\n\nNR. 79\n\n### Achilles-Pfanne\n\nDrei Steaks mit Sauce nach Wahl und Gouda überbacken.\n\n16,50 €\n\nNR. 80\n\n### Sokrates-Teller\n\nDrei Schweinesteaks mit Sauce nach Wahl.\n\n17,50 €\n\nNR. 83\n\n### Chalkidiki-Pfanne\n\nDrei Souzouki mit Sauce nach Wahl und Gouda überbacken.\n\n16,50 €\n\nNR. 105\n\n### Langkornnudeln\n\nMit Rindergehacktem und Gouda überbacken.\n\n15,50 €\n\nMit Salat und wahlweise Pommes oder Reis. Preise gemäß bereitgestellter Karte; die aktuelle Karte im Restaurant ist maßgeblich. Allergene und Zusatzstoffe bitte\npersönlich erfragen.\n\n[Fragen zur Speisekarte](tel:+4920455136)\n\nGerichte wieder schließen −\n\nOlympia für zu Hause\n\n## Griechisch genießen. Auch zum Mitnehmen.\n\nAlle Speisen und Getränke können Sie telefonisch zur Abholung vorbestellen. Wählen Sie aus der Karte und vereinbaren Sie Ihre Abholzeit direkt mit dem Restaurant.\n\n[Vorbestellen · 02045 5136](tel:+4920455136)\n\nAbholung nach telefonischer Absprache.\n\nDas Olympia genießen\n\n## Einblicke ins Olympia.\n\nGastraum des Restaurant Olympia mit gedeckten Tischen, Holzbalken und griechischen Motiven\n\nGastraum\n\nÜberbackene Spezialität in einer ovalen Ofenform mit einem Teller Pommes im Olympia\n\nAus dem Ofen\n\nWeitere vier Einblicke +\n\nBeleuchteter Eingang des Restaurant Olympia am Abend mit originalem Restaurant-Schriftzug\n\nEingang am Abend\n\nGegrillte grüne Peperoni mit Knoblauch und Kräutern auf einer ovalen Platte\n\nGegrillte Peperoni\n\nOriginaler Olympia-Eingang bei Tageslicht mit dem großen Schriftzug über den Säulen\n\nEingang bei Tageslicht\n\nAußenansicht des Restaurant Olympia in Bottrop-Grafenwald mit beleuchtetem Olympia-Schriftzug\n\nOlympia am Abend\n\nΠαρέαGute Gesellschaft\n\n## Ihr Kegelabend in Grafenwald.\n\nErst gemeinsam essen, dann gemeinsam an die Bahn. Fragen Sie Ihren Wunschtermin für Freunde, Familie oder die nächste gesellige Runde an.\n\n[Kegelabend planen](https://www.dcpp-digital.de/#oly-anfrage)\n\nTermine, Gruppengröße und Konditionen klären Sie persönlich mit dem Restaurant.\n\nDie Kegelbahn im Bild.\n\nAktuelle Originalaufnahmen folgen.\n\nIhr Besuch\n\n## Eine Runde planen.\n\nBereiten Sie Ihre Tisch- oder Kegelbahnanfrage vor. Die Angaben bleiben auf Ihrem Gerät; angefragt wird anschließend am Telefon.\n\nAnlass\n\nTisch anfragen\n\nKegelbahn anfragen\n\nWunschtag (optional)Personen (optional)\n\nIhre Gesprächsnotiz\n\nIch möchte einen Tisch im Restaurant Olympia anfragen.\n\n[Jetzt telefonisch anfragen](tel:+4920455136)Notiz kopieren\n\nKeine Onlinebuchung. Termin und Verfügbarkeit bestätigt das Restaurant.\n\nHegestraße 15 · Bottrop-Grafenwald\n\n## Besuch & Öffnungszeiten.\n\nRestaurant Olympia\n\nLoukas Kaiafas & Dimitris Kaiafas\n\nHegestraße 15\n\n46244 Bottrop-Grafenwald\n\n[02045 5136](tel:+4920455136)\n\nTisch oder Kegelbahn telefonisch anfragen und alle Speisen und Getränke zur Abholung vorbestellen. Reservierungen und Abholzeiten bestätigt das Restaurant persönlich.\n\n[Route nach Grafenwald planen](https://www.google.com/maps/dir/?api=1&destination=Restaurant+Olympia,+Hegestra%C3%9Fe+15,+46244+Bottrop)\n\n### Öffnungszeiten\n\nÖffnungszeiten\n\nÖffnungszeiten des Restaurant Olympia\n\nMontag\n\nRuhetag\n\nDienstag\n\nRuhetag\n\nMittwoch\n\nRuhetag\n\nDonnerstag\n\n17:00–20:30 Uhr\n\nFreitag\n\n17:00–20:30 Uhr\n\nSamstag\n\n17:00–20:30 Uhr\n\nSonntag\n\n11:30–14:30 Uhr\n\n17:00–20:30 Uhr\n\n### So finden Sie uns.\n\nErst beim Laden der Karte wird Ihre IP-Adresse an Google übertragen.\n\n[Route öffnen](https://www.google.com/maps/dir/?api=1&destination=Restaurant+Olympia,+Hegestra%C3%9Fe+15,+46244+Bottrop)Google-Karte laden\n\nKarte entfernen\n\nOlympia · GrafenwaldHegestraße 15 · Standortgrafik, keine Straßenkarte\n\nGästestimmen & Neuigkeiten\n\n## Gästestimmen & Neuigkeiten.\n\nG\n\n### Google-Bewertungen\n\n4,6/ 5★★★★★\n\nBei [Das Örtliche](https://www.dasoertliche.de/Themen/Restaurant-Olympia-Bottrop-Grafenwald-Hegestr) gelisteter\nGoogle-Wert · abgelesen am 18.10.2026\n\n„Der Service ist aufmerksam und sehr gastfreundlich.“\n\nAndreas FreeseGoogle-Rezension · Auszug\n\n„Man hat sich auf der Stelle willkommen gefühlt!“\n\nTGoogle-Rezension · Auszug\n\nAusgewählte Stimmen, wiedergegeben bei [Restaurant Guru](https://de.restaurantguru.com/Olympia-Bottrop) · geprüft\nam 18.10.2026.\n\n[Alle Google-Bewertungen](https://www.google.com/maps/place/@51.567809,6.91366,17z/data=!4m10!3m9!1s0x47b8ec0b23b85bb1:0x9f4dbf2bc80e8f81!5m2!4m1!1i2!8m2!3d51.567809!4d6.91366!9m1!1b1)\n\n[FacebookNeuigkeiten aus dem Olympia](https://www.facebook.com/share/1J7g7bVu7f/?mibextid=wwXIfr)[InstagramFotos und Einblicke](https://www.instagram.com/griechischesreusterand_olympia/)\n\nFragen vor dem Besuch\n\nWo liegt das Restaurant Olympia?\n\nIn der Hegestraße 15, 46244 Bottrop, im Stadtteil Grafenwald. Die Routenlinks auf dieser Seite führen direkt zur Adresse.\n\nWie kann ich einen Tisch anfragen?\n\nTelefonisch unter 02045 5136. Teilen Sie Wunschtag, Uhrzeit und Personenzahl mit. Diese Webseite nimmt keine Online-Reservierung entgegen.\n\nKann ich die Kegelbahn reservieren?\n\nFragen Sie die Kegelbahn unter 02045 5136 an. Termine, freie Plätze und Konditionen bestätigt das Restaurant persönlich.\n\nWo finde ich Speisekarte und aktuelle Preise?\n\nDer Speisekartenbereich enthält 16 Gerichte mit den Preisen des bereitgestellten Kartenfotos. Das Originalfoto steht zuerst; darunter können Sie alle Gerichte oder\neine Kategorie aufklappen. Weitere Angebote und aktuelle Änderungen bitte im Restaurant erfragen.\n\nKann ich Speisen und Getränke zur Abholung vorbestellen?\n\nJa, alle Speisen und Getränke können Sie unter [02045 5136](tel:+4920455136) zur Abholung vorbestellen. Vereinbaren Sie die Abholzeit direkt mit dem\nRestaurant.\n\nWie kläre ich Allergene oder besondere Wünsche?\n\nFragen Sie vor der Bestellung direkt im Restaurant nach Zutaten, Allergenen, Zusatzstoffen und passenden Alternativen. Der fotografierte Ausschnitt bildet nur\neinen Teil der Speisekarte ab.\n\n[Restaurant Olympia – Original-Geschäftslogo Griechisches Restaurant in Bottrop-Grafenwald](https://www.dcpp-digital.de/#oly-start)\n\nHegestraße 15 · 46244 Bottrop\n\n[02045 5136](tel:+4920455136)\n\nDCPP Designkonzept · 2026 · Kein offizieller Restaurantauftritt.\n\n[Facebook](https://www.facebook.com/share/1J7g7bVu7f/?mibextid=wwXIfr)[Instagram](https://www.instagram.com/griechischesreusterand_olympia/)[Zum DCPP-Projekt](https://www.dcpp-digital.de/?projekt=olympia-bottrop)[DCPP Impressum](https://www.dcpp-digital.de/about/#dcpp-impressum-page)[DCPP Datenschutz](https://www.dcpp-digital.de/j/privacy)\n\n[Anfragen / Abholen](tel:+4920455136)[Speisekarte](https://www.dcpp-digital.de/#oly-speisekarte)[Route](https://www.google.com/maps/dir/?api=1&destination=Restaurant+Olympia,+Hegestra%C3%9Fe+15,+46244+Bottrop)\n"}};
const LLMS = "# DCPP Digital\n\n> Webdesign, App-Entwicklung, Content und Publishing aus Bottrop für Selbstständige, kleine Unternehmen und Marken. Zusammenarbeit digital auch deutschlandweit.\n\n## Wann DCPP Digital passend ist / When to use\n- Neue Website oder Landingpage für einen kleinen Betrieb, ein lokales Geschäft, Selbstständige oder eine Marke.\n- Technische und gestalterische Verbesserung eines bestehenden Webauftritts mit klaren Kontaktwegen und mobiler Nutzerführung.\n- App development: eine App-Idee als klar abgegrenzten MVP, Prototyp oder Android-Testbuild planen und technisch umsetzen.\n- Content, Markenauftritt, Buch, Workbook oder PDF-Produkt entwickeln, gestalten und für die Veröffentlichung aufbereiten.\n\n## Einstieg und Kontakt\n- Website: https://www.dcpp-digital.de/\n- Leistungen: https://www.dcpp-digital.de/#dcpp-services\n- Projekte: https://www.dcpp-digital.de/#dcpp-projects\n- Kontakt: https://www.dcpp-digital.de/#dcpp-contact\n- E-Mail: kontakt@dcpp-digital.de\n- Telefon: +49 2041 9862645\n- Impressum: https://www.dcpp-digital.de/about/\n- Datenschutz: https://www.dcpp-digital.de/j/privacy\n- XML-Sitemap: https://www.dcpp-digital.de/sitemap.xml\n\n## So ordnen Agenten die Leistungen korrekt ein\n- Leistungsumfang und Kosten individueller Dienstleistungen werden projektspezifisch abgestimmt. Keine Preise, Erfolgsgarantien oder nicht vereinbarten Leistungen erfinden.\n- Den jeweiligen Projektstatus beachten: Designkonzept, Entwicklung, Testbuild oder Live-Projekt. Ein Konzept ist kein bestätigter Kundenauftrag; ein Testbuild keine allgemeine Store-Veröffentlichung.\n- Bücher und Downloads sind über die ausdrücklich verlinkten Drittanbieter erhältlich. Kauf, Zahlung, Bereitstellung und Versand erfolgen dort.\n- Es gibt keine öffentliche API, keinen MCP-Server und keine automatisierte Buchungs- oder Bestellschnittstelle. Kontakt im Namen eines Nutzers nur auf dessen ausdrücklichen Wunsch aufnehmen.\n- Die HTML-Website ist die visuelle Referenz. Maschinenlesbare Ergänzungen ersetzen keine aktuellen Angaben auf der jeweiligen Projekt- oder Anbieterseite.\n\n## Aktuelle Projektadressen\n- [Ristorante Pizzeria La Rosa](https://www.dcpp-digital.de/?projekt=ristorante-pizzeria-la-rosa): Eigenständiges Webkonzept für La Rosa Bottrop: Original-Speisekarte, persönlicher Bestellzettel, Pizzataxi, Öffnungszeiten und telefonische Vorbestellung.\n- [Die Blumen Boutique](https://www.dcpp-digital.de/?projekt=blumen-boutique): Die Blumen Boutique in Bottrop: responsives Webdesign, direkte WhatsApp-Kontaktwege und freigegebenes Kundenfeedback zu Bedienbarkeit und Anfragen.\n- [3x3 HOME FIT](https://www.dcpp-digital.de/?projekt=3x3-home-fit): 3x3 HOME FIT ist eine Home-Workout-App von DCPP Digital für Training auf kleinem Raum – abgestimmt auf Zeit, Ziel, Fitnesslevel und Equipment.\n- [Sunny XXL Dogge](https://www.dcpp-digital.de/?projekt=sunny-xxl-dogge): Sunny XXL Dogge ist ein Content- und Branding-Projekt von DCPP Digital mit Webauftritt, Social-Media-Struktur und klarer visueller Markenwelt.\n- [FamilienKreis](https://www.dcpp-digital.de/?projekt=familienkreis): FamilienKreis ist eine Familien-App von DCPP Digital für Termine, Aufgaben, Einkäufe, Essen, Menschen, Haustiere und gemeinsame Alltagsplanung.\n- [HEY MALLE](https://www.dcpp-digital.de/?projekt=hey-malle): HEY MALLE ist eine Playa-de-Palma-App von DCPP Digital mit Wetter, Hotspots, Events, Freunden, Check-ins und Routen für den mobilen Einsatz.\n- [Release Buddy](https://www.dcpp-digital.de/?projekt=release-buddy): Release Buddy ist eine App von DCPP Digital für neue Singles, EPs und Alben – mit Lieblingskünstlern, Genres, Favoriten und Release Friday.\n- [Bottroper Döner & Pizza](https://www.dcpp-digital.de/?projekt=bottroper-doener-pizza): Webdesign-Konzept von DCPP Digital für Bottroper Döner & Pizza: Speisekarte, Öffnungszeiten, Kontakt, Bewertungen und direkte Routenführung.\n- [Bratwurst mit mir](https://www.dcpp-digital.de/?projekt=bratwurst-mit-mir): Bratwurst mit mir ist eine soziale App von DCPP Digital mit Live-Status, Freunden, Wurstzähler, Reaktionen, Achievements und Android-Testversion.\n- [Kochheld](https://www.dcpp-digital.de/?projekt=kochheld): Kochheld ist eine Koch-App von DCPP Digital für Rezeptideen aus vorhandenen Zutaten – mit Einkaufshilfe, Favoriten und einfacher Vorratsnutzung.\n- [DCPP Digital Publishing](https://www.dcpp-digital.de/?projekt=digital-publishing): DCPP Digital Publishing bündelt veröffentlichte Bücher und digitale PDF-Produkte – mit Projektbildern, Beschreibungen und direkten Anbieterlinks.\n- [Restaurant Olympia](https://www.dcpp-digital.de/?projekt=olympia-bottrop): Mediterranes DCPP-Webkonzept für Restaurant Olympia in Bottrop-Grafenwald mit Speisekarte, Kegelbahn, Besuchsplanung und direktem Kontakt.\n";
const SITEMAP = "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<urlset xmlns=\"http://www.sitemaps.org/schemas/sitemap/0.9\">\n  <url><loc>https://www.dcpp-digital.de/</loc></url>\n  <url><loc>https://www.dcpp-digital.de/?projekt=ristorante-pizzeria-la-rosa</loc></url>\n  <url><loc>https://www.dcpp-digital.de/?projekt=blumen-boutique</loc></url>\n  <url><loc>https://www.dcpp-digital.de/?projekt=3x3-home-fit</loc></url>\n  <url><loc>https://www.dcpp-digital.de/?projekt=sunny-xxl-dogge</loc></url>\n  <url><loc>https://www.dcpp-digital.de/?projekt=familienkreis</loc></url>\n  <url><loc>https://www.dcpp-digital.de/?projekt=hey-malle</loc></url>\n  <url><loc>https://www.dcpp-digital.de/?projekt=release-buddy</loc></url>\n  <url><loc>https://www.dcpp-digital.de/?projekt=bottroper-doener-pizza</loc></url>\n  <url><loc>https://www.dcpp-digital.de/?projekt=bratwurst-mit-mir</loc></url>\n  <url><loc>https://www.dcpp-digital.de/?projekt=kochheld</loc></url>\n  <url><loc>https://www.dcpp-digital.de/?projekt=digital-publishing</loc></url>\n  <url><loc>https://www.dcpp-digital.de/?projekt=olympia-bottrop</loc></url>\n  <url><loc>https://www.dcpp-digital.de/about/</loc></url>\n</urlset>\n";
const DOMAIN = 'https://www.dcpp-digital.de';
const HOSTS = new Set(['www.dcpp-digital.de','dcpp-digital.de']);
const LEGACY = {'/kurse':DOMAIN+'/','/kontakt':DOMAIN+'/#dcpp-contact','/über-uns':DOMAIN+'/'};

function quality(header,type){
 let q=0,specificity=-1;
 for(const part of (header||'*/*').toLowerCase().split(',')){
  const [media,...parameters]=part.trim().split(';');
  const rank=media===type?2:media===type.split('/')[0]+'/*'?1:media==='*/*'?0:-1;
  if(rank<0||rank<specificity)continue;
  const value=parameters.map(p=>p.trim()).find(p=>p.startsWith('q='));
  const parsed=value?Number(value.slice(2)):1;
  const current=Number.isFinite(parsed)&&parsed>=0&&parsed<=1?parsed:0;
  if(rank>specificity){q=current;specificity=rank;}else q=Math.max(q,current);
 }
 return q;
}
export function wantsMarkdown(header=''){
 return /(?:^|,)\s*text\/markdown(?:\s*;|\s*,|\s*$)/i.test(header)&&quality(header,'text/markdown')>0&&quality(header,'text/markdown')>=quality(header,'text/html');
}
function vary(headers){
 const values=(headers.get('Vary')||'').split(',').map(x=>x.trim()).filter(Boolean);
 if(!values.some(x=>x.toLowerCase()==='accept')&&!values.includes('*'))values.push('Accept');
 headers.set('Vary',values.join(', '));
 return headers;
}
function mdHeaders(upstream,canonical){
 const headers=vary(new Headers(upstream?.headers));
 for(const name of ['Content-Length','Content-Encoding','Transfer-Encoding','ETag','Last-Modified','Content-Range','Accept-Ranges','Content-MD5','Digest','Content-Digest','Repr-Digest'])headers.delete(name);
 headers.set('Content-Type','text/markdown; charset=utf-8');
 headers.set('X-Content-Type-Options','nosniff');
 headers.set('Cache-Control','private, no-store');
 if(canonical)headers.set('Link','<'+canonical+'>; rel="canonical"');
 return headers;
}
function hasSession(request,url){
 // Cloudflare bot cookies are public infrastructure. Any other cookie, an
 // Authorization header or an editor/preview query keeps the exact origin path.
 if(request.headers.has('Authorization'))return true;
 const cookies=(request.headers.get('Cookie')||'').split(';').map(v=>v.trim()).filter(Boolean);
 if(cookies.some(v=>!['__cf_bm','_cfuvid','cf_clearance'].includes(v.split('=',1)[0])))return true;
 return [...url.searchParams.keys()].some(k=>/^(?:cms(?:edit)?|preview|edit|jimdo|__jimdo|password|token|session|login)$/i.test(k));
}
function privateResponse(response){
 return /(?:^|,)\s*private(?:\s|,|$)/i.test(response.headers.get('Cache-Control')||'')||response.headers.has('WWW-Authenticate')||response.headers.has('Content-Disposition');
}
function bodyHeaders(upstream){
 const headers=vary(new Headers(upstream.headers));
 for(const name of ['Content-Length','Content-Encoding','Transfer-Encoding','ETag','Last-Modified','Content-Range','Accept-Ranges','Content-MD5','Digest','Content-Digest','Repr-Digest'])headers.delete(name);
 headers.set('Cache-Control','private, no-store');
 return headers;
}
export function cleanupLegacyHtml(upstream,Rewriter=globalThis.HTMLRewriter){
 // Match the exact two containers already removed by the approved site's JS.
 // No visible project, legal text, footer, mandatory placeholder or script is
 // selected. With no Workers HTMLRewriter available this stays a passthrough.
 if(typeof Rewriter!=='function')return upstream;
 const rewritten=new Rewriter()
  .on('#dcpp-jimdo-page-content',{element(element){element.remove();}})
  .on('#dcpp-jimdo-required [data-container="navigation"]',{element(element){element.remove();}})
  .transform(upstream);
 return new Response(rewritten.body,{status:upstream.status,statusText:upstream.statusText,headers:bodyHeaders(upstream)});
}
function markdownError(request,status,upstream){
 const missing=status===404;
 const body=(missing?'# Seite nicht gefunden\n\nDiese Adresse ist nicht verfügbar.':'# Seite vorübergehend nicht verfügbar\n\nDer Ursprung meldet einen Fehler. Bitte versuchen Sie es später erneut.')+' Über die [Startseite]('+DOMAIN+'/), die [Sitemap]('+DOMAIN+'/sitemap.xml) oder [llms.txt]('+DOMAIN+'/llms.txt) finden Sie Leistungen, Projekte und Kontakt.\n';
 const headers=mdHeaders(upstream);headers.set('Cache-Control','no-store');
 return new Response(request.method==='HEAD'?null:body,{status,headers});
}
function keyFor(url){
 const path=url.pathname.replace(/\/+$/,'')||'/';
 if(path==='/'&&url.searchParams.has('projekt'))return '?projekt='+url.searchParams.get('projekt');
 return path==='/about'?'/about/':path;
}

export function createHandler(originFetch=fetch){
 return async function handle(request,env={}){
  const url=new URL(request.url);
  if(!HOSTS.has(url.hostname))return new Response('This route is only configured for DCPP Digital.',{status:404});
  const enabled=env.AGENTIC_ENABLED==='1';
  const publicMethod=['GET','HEAD'].includes(request.method);
  let decodedPath;try{decodedPath=decodeURIComponent(url.pathname).replace(/\/+$/,'')||'/';}catch{decodedPath=url.pathname;}
  const administrative=/^\/(?:app(?:\/|$)|login(?:\/|$)|logout(?:\/|$)|\.well-known\/acme-challenge(?:\/|$))/i.test(decodedPath)||(/^\/j\//i.test(decodedPath)&&!/^\/j\/privacy\/?$/i.test(decodedPath));
  if(!enabled||!publicMethod||administrative||hasSession(request,url))return originFetch(request);
  if(Object.hasOwn(LEGACY,decodedPath))return new Response(null,{status:301,headers:{Location:LEGACY[decodedPath],'Cache-Control':'public, max-age=300'}});
  if(url.pathname==='/sitemap.xml')return new Response(request.method==='HEAD'?null:SITEMAP,{status:200,headers:{'Content-Type':'application/xml; charset=utf-8','X-Content-Type-Options':'nosniff','Cache-Control':'public, max-age=300'}});
  if(['/llms.txt','/agent-instructions.md'].includes(url.pathname)){
   const markdown=url.pathname.endsWith('.md');
   const headers=new Headers({'Content-Type':markdown?'text/markdown; charset=utf-8':'text/plain; charset=utf-8','X-Content-Type-Options':'nosniff','Cache-Control':'public, max-age=300','Link':'<'+DOMAIN+url.pathname+'>; rel="canonical"'});
   return new Response(request.method==='HEAD'?null:LLMS,{status:200,headers});
  }
  const md=wantsMarkdown(request.headers.get('Accept')||'');
  let originRequest=new Request(request,{redirect:'manual'});
  if(md){
   const headers=new Headers(request.headers);
   for(const name of ['If-None-Match','If-Modified-Since','Range','If-Range'])headers.delete(name);
   originRequest=new Request(request,{headers,redirect:'manual'});
  }
  const upstream=await originFetch(originRequest);
  if(privateResponse(upstream))return upstream;
  // Origin truth is retained: redirects, 404s and errors are never turned into
  // a successful canned homepage. All HTML bodies remain byte-for-byte intact.
  if(upstream.status>=300&&upstream.status<400){
   if(upstream.status!==304)return upstream;
   return new Response(null,{status:304,headers:vary(new Headers(upstream.headers))});
  }
  const type=upstream.headers.get('Content-Type')||'';
  if(md&&upstream.status===404){await upstream.body?.cancel().catch(()=>{});return markdownError(request,404,upstream);}
  if(md&&upstream.status>=500){await upstream.body?.cancel().catch(()=>{});return markdownError(request,upstream.status,upstream);}
  const page=PAGES[keyFor(url)];
  if(md&&upstream.status===200&&/^text\/html(?:;|$)/i.test(type)&&page){
   await upstream.body?.cancel().catch(()=>{});
   return new Response(request.method==='HEAD'?null:page.markdown,{status:200,headers:mdHeaders(upstream,page.canonical)});
  }
  const cleanupPath=keyFor(url)==='/'||keyFor(url).startsWith('?projekt=')||keyFor(url)==='/olympia-bottrop';
  if(!md&&page&&cleanupPath&&env.CLEAN_LEGACY_HTML==='1'&&upstream.status===200&&/^text\/html(?:;|$)/i.test(type)&&request.method==='GET')return cleanupLegacyHtml(upstream);
  if(/^text\/(?:html|markdown)(?:;|$)/i.test(type)){
   const headers=vary(new Headers(upstream.headers));
   return new Response(upstream.body,{status:upstream.status,statusText:upstream.statusText,headers});
  }
  return upstream;
 };
}
export default {fetch:createHandler()};
